Show that the following functions have exactly one zero in the given interval.
    \begin{enumerate}[label=(\roman*)]
      {\item $f(x) = x^4 + 3x + 1$, \quad $[-2, -1]$}
      {\item $f(x) = \dfrac{x^3 + 4}{x^2 + 7}$, \quad $(-\infty, 0)$}
      {\item $f(\theta) = 2\theta - \cos^2\theta + \sqrt{2}$, \quad $(-\infty, \infty)$}
      {\item $f(\theta) = \tan\theta - \cot\theta - \theta$, \quad $\left(0, \dfrac{\pi}{2}\right)$}
    \end{enumerate}

Find the local and global extrema (if any) of the following functions:
    \begin{enumerate}[label=(\roman*)]
      {\item $f(x) = \sin x - \cos x$, \quad $0 \leq x \leq 2\pi$}
      {\item $f(x) = x^3 - 3x^2$, \quad $-\infty < x \leq 3$}
      {\item $f(x) = \dfrac{x - 2}{x^2 - 1}$, \quad $0 \leq x < 1$}
      {\item $f(x) = \sec^2 x - 2\tan x$, \quad $-\dfrac{\pi}{2} < x < \dfrac{\pi}{2}$}
    \end{enumerate}

Solution:
\begin{proof}
    To show that $f(4) - f(1) \leq 3$, we will apply the Mean Value Theorem.

    \textbf{1. Verification of Hypotheses}
    The problem states that the derivative $f'(x)$ exists and satisfies $f'(x) \leq 1$ for all $x$ in the interval $[1, 4]$. The existence of the derivative on the closed interval $[1, 4]$ implies two necessary conditions:
    \begin{enumerate}
        \item $f$ is continuous on the closed interval $[1, 4]$.
        \item $f$ is differentiable on the open interval $(1, 4)$.
    \end{enumerate}
    Since these conditions are met, the Mean Value Theorem applies to $f$ on $[1, 4]$.

    \textbf{2. Application of the Mean Value Theorem}
    According to the Mean Value Theorem, there exists at least one number $c$ in the open interval $(1, 4)$ such that:
    \begin{equation*}
        f'(c) = \frac{f(4) - f(1)}{4 - 1}.
    \end{equation*}
    Simplifying the denominator, we have:
    \begin{equation} \label{eq:mvt}
        f'(c) = \frac{f(4) - f(1)}{3}.
    \end{equation}

    \textbf{3. Utilizing the Bound on the Derivative}
    We are given the hypothesis that $f'(x) \leq 1$ for all $x$ such that $1 \leq x \leq 4$. Since $c \in (1, 4)$, this inequality holds for $c$:
    \begin{equation*}
        f'(c) \leq 1.
    \end{equation*}
    Substituting the expression for $f'(c)$ from Equation (\ref{eq:mvt}) into this inequality, we obtain:
    \begin{equation*}
        \frac{f(4) - f(1)}{3} \leq 1.
    \end{equation*}

    \textbf{4. Conclusion}
    Multiplying both sides of the inequality by 3 (which preserves the direction of the inequality since $3 > 0$), we arrive at the desired result:
    \begin{equation*}
        f(4) - f(1) \leq 3.
    \end{equation*}
\end{proof}

