    \item{ $\displaystyle \int_0^{1} x^m \left(\ln \left(\frac{1}{x} \right) \right)^n \, dx$ }
    \item{ $\displaystyle \int_0^{\pi/2} \sin^4 \theta \cos^6 \theta \, d\theta$ }
  \end{itemize}

Find the volume of the solids generated by revolving the regions bounded by the lines and curves in the following exercises about the $x$-axis.
    \begin{itemize}
        \item{ $y = x^2$, $y = 0$, $x = 2$ }
        \item{ $y = \sqrt{\cos x}$, $0 \leq x \leq \frac{\pi}{2}$, $y = 0$, $x = 0$ }
        \item{ $y = e^{-x}$, $y = 0$, $x = 0$, $x = 1$ }
        \item{ $y = x^2 + 1$, $y = x + 3$ }
    \end{itemize}

Solution:
To find the volume of a solid of revolution generated by revolving a region about the $x$-axis, we utilize the method of disks or washers.

**General Formulas:**
\begin{enumerate}
    \item \textbf{Disk Method:} If the region is bounded by $y=f(x)$, the $x$-axis, and the lines $x=a$ and $x=b$, the volume $V$ is given by:
    \[ V = \pi \int_{a}^{b} [f(x)]^2 \, dx \]
    \item \textbf{Washer Method:} If the region is bounded by an upper curve $y=R(x)$ and a lower curve $y=r(x)$ between $x=a$ and $x=b$, the volume $V$ is given by:
    \[ V = \pi \int_{a}^{b} \left([R(x)]^2 - [r(x)]^2 \right) \, dx \]
\end{enumerate}

\begin{enumerate}
    % Problem 1
    \item \textbf{Region bounded by:} $y = x^2$, $y = 0$, $x = 2$.

    \textbf{Analysis:}
    The region is bounded above by the parabola $y=x^2$ and below by the $x$-axis ($y=0$). The vertical boundary is $x=2$. The curve $y=x^2$ intersects the line $y=0$ at $x=0$. Thus, the interval of integration is $[0, 2]$.

    Since the region is adjacent to the axis of revolution ($x$-axis), we use the \textbf{Disk Method}.

    \textbf{Calculation:}
    \begin{align*}
        V &= \pi \int_{0}^{2} (x^2)^2 \, dx \\
          &= \pi \int_{0}^{2} x^4 \, dx \\
          &= \pi \left[ \frac{x^5}{5} \right]_{0}^{2} \\
          &= \pi \left(\frac{2^5}{5} - \frac{0^5}{5} \right) \\
          &= \frac{32\pi}{5}
    \end{align*}

    The volume of the solid is $\boxed{\frac{32\pi}{5}}$.

    % Problem 2
    \item \textbf{Region bounded by:} $y = \sqrt{\cos x}$, $0 \leq x \leq \frac{\pi}{2}$, $y = 0$, $x = 0$.

    \textbf{Analysis:}
    The region lies under the curve $y = \sqrt{\cos x}$ and above the $x$-axis. The limits of integration are explicitly given as $x=0$ to $x=\frac{\pi}{2}$. Note that $\cos x \geq 0$ on this interval, so the function is real-valued.

    We use the \textbf{Disk Method}.

    \textbf{Calculation:}
    \begin{align*}
        V &= \pi \int_{0}^{\frac{\pi}{2}} \left(\sqrt{\cos x}\right)^2 \, dx \\
          &= \pi \int_{0}^{\frac{\pi}{2}} \cos x \, dx \\
          &= \pi \Big[ \sin x \Big]_{0}^{\frac{\pi}{2}} \\
          &= \pi \left(\sin\left(\frac{\pi}{2}\right) - \sin(0) \right) \\
          &= \pi (1 - 0) \\
          &= \pi
    \end{align*}

    The volume of the solid is $\boxed{\pi}$.

    % Problem 3
    \item \textbf{Region bounded by:} $y = e^{-x}$, $y = 0$, $x = 0$, $x = 1$.

    \textbf{Analysis:}
    The region is bounded above by the exponential decay function $y = e^{-x}$ and below by the $x$-axis. The vertical boundaries are $x=0$ and $x=1$.

    We use the \textbf{Disk Method}.

    \textbf{Calculation:}
    \begin{align*}
        V &= \pi \int_{0}^{1} (e^{-x})^2 \, dx \\
          &= \pi \int_{0}^{1} e^{-2x} \, dx \\
          &= \pi \left[ -\frac{1}{2}e^{-2x} \right]_{0}^{1} \\
          &= -\frac{\pi}{2} \left(e^{-2(1)} - e^{-2(0)} \right) \\
          &= -\frac{\pi}{2} (e^{-2} - 1) \\
          &= \frac{\pi}{2} (1 - e^{-2})
    \end{align*}

    The volume of the solid is $\boxed{\frac{\pi}{2}(1 - e^{-2})}$.

    % Problem 4
    \item \textbf{Region bounded by:} $y = x^2 + 1$, $y = x + 3$.

    \textbf{Analysis:}
    Here, the region is bounded between a parabola opening upward ($y = x^2 + 1$) and a straight line ($y = x + 3$). Neither boundary is the axis of revolution ($y=0$). Therefore, we must use the \textbf{Washer Method}.

    First, we determine the points of intersection to find the limits of integration:
    \begin{align*}
        x^2 + 1 &= x + 3 \\
        x^2 - x - 2 &= 0 \\
        (x - 2)(x + 1) &= 0
    \end{align*}
    The curves intersect at $x = -1$ and $x = 2$.

    Next, we determine the outer radius $R(x)$ and inner radius $r(x)$ on the interval $[-1, 2]$. Testing a point $x=0$:
    \[ y_{\text{parabola}} = 0^2 + 1 = 1, \quad y_{\text{line}} = 0 + 3 = 3. \]
    Since $x+3 > x^2+1$ on the interval, the line is the outer curve and the parabola is the inner curve.
    \[ R(x) = x + 3, \quad r(x) = x^2 + 1 \]

    \textbf{Calculation:}
    \begin{align*}
        V &= \pi \int_{-1}^{2} \left([x + 3]^2 - [x^2 + 1]^2 \right) \, dx \\
          &= \pi \int_{-1}^{2} \left((x^2 + 6x + 9) - (x^4 + 2x^2 + 1) \right) \, dx \\
          &= \pi \int_{-1}^{2} \left(-x^4 - x^2 + 6x + 8 \right) \, dx \\
          &= \pi \left[ -\frac{x^5}{5} - \frac{x^3}{3} + 3x^2 + 8x \right]_{-1}^{2}
    \end{align*}

    We evaluate the antiderivative at the limits:
    \begin{align*}
        F(2) &= -\frac{32}{5} - \frac{8}{3} + 3(4) + 8(2) = -\frac{32}{5} - \frac{8}{3} + 28 \\
        F(-1) &= -\frac{(-1)^5}{5} - \frac{(-1)^3}{3} + 3(-1)^2 + 8(-1) = \frac{1}{5} + \frac{1}{3} + 3 - 8 = \frac{1}{5} + \frac{1}{3} - 5
    \end{align*}

    Subtracting $F(-1)$ from $F(2)$:
    \begin{align*}
        V &= \pi \left(\left(28 - \frac{32}{5} - \frac{8}{3} \right) - \left(-5 + \frac{1}{5} + \frac{1}{3} \right) \right) \\
          &= \pi \left(28 + 5 - \frac{32}{5} - \frac{1}{5} - \frac{8}{3} - \frac{1}{3} \right) \\
          &= \pi \left(33 - \frac{33}{5} - \frac{9}{3} \right) \\
          &= \pi \left(33 - \frac{33}{5} - 3 \right) \\
          &= \pi \left(30 - \frac{33}{5} \right) \\
          &= \pi \left(\frac{150}{5} - \frac{33}{5} \right) \\
          &= \frac{117\pi}{5}
    \end{align*}

    The volume of the solid is $\boxed{\frac{117\pi}{5}}$.
\end{enumerate}

