latexcode:
In each of the following cases below, the discriminant is zero. Find the critical points and their nature by imagining the surface $z = f(x, y)$:
    \begin{enumerate}[label=(\alph*)]
      {\item $f(x, y) = x^2y^2$}
      {\item $f(x, y) = 1 - x^2y^2$}
      {\item $f(x, y) = xy^2$}
    \end{enumerate}

Examine if the limits as $(x, y) \to (0, 0)$ exist:
    \begin{enumerate}[label=(\alph*)]
      {\item $\frac{x^3 + y^3}{x^2 - y^2}$ for $x \neq y$, and 0 for $x = y$}
      {\item $xy \left(\frac{x^2 - y^2}{x^2 + y^2}\right)$}
      {\item $x \sin\left(\frac{1}{x}\right) + y \sin\left(\frac{1}{y}\right)$ if $xy \neq 0$, and 0 if $xy = 0$}
      {\item $\frac{\sin(xy)}{x^2 + y^2}$}
    \end{enumerate}

Solution:
\begin{enumerate}[label=(\alph*)]

\item \textbf{Analyze the limit of} $\displaystyle \frac{x^3 + y^3}{x^2 - y^2}$.

Let $f(x, y) = \frac{x^3 + y^3}{x^2 - y^2}$ for $x \neq y$. We can simplify the expression by factoring the numerator and the denominator:
\begin{align*}
f(x, y) &= \frac{(x+y)(x^2 - xy + y^2)}{(x-y)(x+y)} \\
&= \frac{x^2 - xy + y^2}{x - y}, \quad \text{provided } x \neq -y.
\end{align*}
To determine if the limit exists, we examine the behavior of $f(x, y)$ along different paths approaching the origin $(0, 0)$.

\textbf{Path 1:} Approach along the $x$-axis ($y = 0$).
\begin{align*}
\lim_{x \to 0} f(x, 0) &= \lim_{x \to 0} \frac{x^2 - x(0) + 0^2}{x - 0} \\
&= \lim_{x \to 0} \frac{x^2}{x} = \lim_{x \to 0} x = 0.
\end{align*}

\textbf{Path 2:} Approach along the curve $y = x - x^2$.
Note that as $x \to 0$, $(x, x-x^2) \to (0,0)$. Along this path, the denominator becomes $x - (x - x^2) = x^2$. The numerator becomes:
\begin{align*}
x^2 - x(x-x^2) + (x-x^2)^2 &= x^2 - (x^2 - x^3) + (x^2 - 2x^3 + x^4) \\
&= x^2 - x^2 + x^3 + x^2 - 2x^3 + x^4 \\
&= x^2 - x^3 + x^4.
\end{align*}
Substituting these into the simplified expression for $f(x, y)$:
\begin{align*}
\lim_{x \to 0} f(x, x-x^2) &= \lim_{x \to 0} \frac{x^2 - x^3 + x^4}{x^2} \\
&= \lim_{x \to 0} \left(1 - x + x^2\right) = 1.
\end{align*}

Since the limit is $0$ along the path $y=0$ and $1$ along the path $y = x - x^2$, the limit \textbf{does not exist}.

\vspace{0.5cm}

\item \textbf{Analyze the limit of} $\displaystyle xy \left(\frac{x^2 - y^2}{x^2 + y^2}\right)$.

Let $f(x, y) = xy \left(\frac{x^2 - y^2}{x^2 + y^2}\right)$. We employ polar coordinates to analyze the limit. Let $x = r\cos\theta$ and $y = r\sin\theta$. As $(x, y) \to (0, 0)$, $r \to 0^+$.

Substituting these into the expression:
\begin{align*}
f(r\cos\theta, r\sin\theta) &= (r\cos\theta)(r\sin\theta) \left(\frac{r^2\cos^2\theta - r^2\sin^2\theta}{r^2\cos^2\theta + r^2\sin^2\theta} \right) \\
&= r^2 \cos\theta \sin\theta \left(\frac{r^2(\cos^2\theta - \sin^2\theta)}{r^2(\cos^2\theta + \sin^2\theta)} \right).
\end{align*}
Using the trigonometric identities $\sin(2\theta) = 2\sin\theta\cos\theta$ and $\cos(2\theta) = \cos^2\theta - \sin^2\theta$, and noting that $\cos^2\theta + \sin^2\theta = 1$, we obtain:
\begin{align*}
f(r, \theta) &= r^2 \left(\frac{1}{2}\sin(2\theta)\right) \left(\cos(2\theta)\right) \\
&= \frac{1}{2}r^2 \sin(2\theta)\cos(2\theta) \\
&= \frac{1}{4}r^2 \sin(4\theta).
\end{align*}
We now apply the Squeeze Theorem. Since $|\sin(4\theta)| \leq 1$ for all $\theta$:
\begin{align*}
0 \leq \left| f(x, y) \right| = \left| \frac{1}{4}r^2 \sin(4\theta) \right| \leq \frac{1}{4}r^2.
\end{align*}
As $(x, y) \to (0, 0)$, $r \to 0$, and consequently $\frac{1}{4}r^2 \to 0$.
Therefore, by the Squeeze Theorem, the limit \textbf{exists and is equal to 0}.

\vspace{0.5cm}

\item \textbf{Analyze the limit of} $\displaystyle x \sin\left(\frac{1}{x}\right) + y \sin\left(\frac{1}{y}\right)$.

Let $f(x, y) = x \sin\left(\frac{1}{x}\right) + y \sin\left(\frac{1}{y}\right)$ for $xy \neq 0$, and $f(x,y) = 0$ if $xy=0$.
We evaluate the limit as $(x, y) \to (0, 0)$ using the Squeeze Theorem.

Recall that for any real number $\alpha$, $|\sin(\alpha)| \leq 1$. Therefore:
\begin{align*}
\left| \sin\left(\frac{1}{x}\right) \right| \leq 1 \quad \text{and} \quad \left| \sin\left(\frac{1}{y}\right) \right| \leq 1.
\end{align*}
We can bound the absolute value of the function:
\begin{align*}
|f(x, y)| &= \left| x \sin\left(\frac{1}{x}\right) + y \sin\left(\frac{1}{y}\right) \right| \\
&\leq \left| x \sin\left(\frac{1}{x}\right) \right| + \left| y \sin\left(\frac{1}{y}\right) \right| \quad (\text{Triangle Inequality}) \\
&= |x| \left| \sin\left(\frac{1}{x}\right) \right| + |y| \left| \sin\left(\frac{1}{y}\right) \right| \\
&\leq |x|(1) + |y|(1) \\
&= |x| + |y|.
\end{align*}
This inequality holds for $xy \neq 0$. If $xy = 0$, $f(x,y) = 0$, and since $0 \leq |x| + |y|$, the inequality $|f(x,y)| \leq |x| + |y|$ holds for all $(x,y)$ in the domain.

Now, consider the limit of the upper bound as $(x, y) \to (0, 0)$:
\begin{align*}
\lim_{(x, y) \to (0, 0)} (|x| + |y|) = 0.
\end{align*}
Since $0 \leq |f(x, y)| \leq |x| + |y|$, by the Squeeze Theorem, the limit \textbf{exists and is equal to 0}.

\vspace{0.5cm}

\item \textbf{Analyze the limit of} $\displaystyle \frac{\sin(xy)}{x^2 + y^2}$.

Let $f(x, y) = \frac{\sin(xy)}{x^2 + y^2}$. We test different paths approaching the origin.

\textbf{Path 1:} Approach along the $x$-axis ($y = 0$).
\begin{align*}
\lim_{x \to 0} f(x, 0) = \lim_{x \to 0} \frac{\sin(0)}{x^2 + 0} = \lim_{x \to 0} 0 = 0.
\end{align*}

\textbf{Path 2:} Approach along the line $y = x$.
\begin{align*}
\lim_{x \to 0} f(x, x) &= \lim_{x \to 0} \frac{\sin(x^2)}{x^2 + x^2} \\
&= \lim_{x \to 0} \frac{\sin(x^2)}{2x^2} \\
&= \frac{1}{2} \lim_{x \to 0} \frac{\sin(x^2)}{x^2}.
\end{align*}
Let $u = x^2$. As $x \to 0$, $u \to 0^+$. Using the standard limit $\lim_{u \to 0} \frac{\sin u}{u} = 1$, we get:
\begin{align*}
\frac{1}{2} \cdot 1 = \frac{1}{2}.
\end{align*}

Since the limit is $0$ along $y=0$ and $\frac{1}{2}$ along $y=x$, the limit \textbf{does not exist}.

\end{enumerate}

\hfill [Generated by gemini-3-pro]

latexcode:
Examine the continuity of the following functions:
    \begin{enumerate}[label=(\alph*)]
      {\item $\frac{xy^3}{x^2 + y^6}$ for $(x, y) \neq (0, 0)$, and 0 otherwise}
      {\item $x^2 + y^2$ if $x^2 + y^2 \leq 1$, and 0 otherwise}
      {\item $\frac{\sin^2(x - y)}{|x| + |y|}$ for $(x, y) \neq (0, 0)$, and 0 otherwise}
      {\item $\frac{x^2y^2}{x^2y^2 + (x - y)^2}$ for $(x, y) \neq (0, 0)$, and 0 otherwise}
    \end{enumerate}

Discuss the differentiability of the following functions at $(0, 0)$:
    \begin{enumerate}[label=(\alph*)]
      {\item $x \sin\left(\frac{1}{x}\right) + y \sin\left(\frac{1}{y}\right)$ if $xy \neq 0$, and 0 if $xy = 0$}
      {\item $\frac{xy}{\sqrt{x^2 + y^2}}$ for $x^2 + y^2 \neq 0$, and 0 at $(0, 0)$}
      {\item $\frac{x^6 - 2y^4}{x^2 + y^2}$ if $x^2 + y^2 \neq 0$, and 0 at $(0, 0)$}
    \end{enumerate}

Solution:
To estimate the values of a differentiable function $f(x, y)$ near a point $(a, b)$, we utilize the **linear approximation** (or tangent plane approximation). The linearization $L(x, y)$ of the function $f$ at the point $(a, b)$ is given by:
\[
L(x, y) = f(a, b) + f_x(a, b)(x - a) + f_y(a, b)(y - b).
\]
For points $(x, y)$ close to $(a, b)$, we have the approximation:
\[
f(x, y) \approx L(x, y).
\]

\subsubsection*{Step 1: Construct the Linearization Function}

We are given the base point $(a, b) = (8, 3)$ and the following values:
\begin{align*}
f(8, 3) &= 24, \\
f_x(8, 3) &= -3.4, \\
f_y(8, 3) &= 4.2.
\end{align*}

Substituting these values into the linearization formula, we obtain:
\begin{align*}
L(x, y) &= 24 + (-3.4)(x - 8) + (4.2)(y - 3) \\
L(x, y) &= 24 - 3.4(x - 8) + 4.2(y - 3).
\end{align*}
We will use this function $L(x, y)$ to estimate the required values.

\subsubsection*{Step 2: Estimate $f(9, 3)$}

Here, we evaluate the function at $x = 9$ and $y = 3$. The changes in the variables are:
\begin{align*}
\Delta x &= x - a = 9 - 8 = 1, \\
\Delta y &= y - b = 3 - 3 = 0.
\end{align*}
Substituting these into our linearization equation:
\begin{align*}
f(9, 3) &\approx L(9, 3) \\
&= 24 - 3.4(1) + 4.2(0) \\
&= 24 - 3.4 \\
&= \mathbf{20.6}.
\end{align*}

\subsubsection*{Step 3: Estimate $f(8, 5)$}

Here, we evaluate the function at $x = 8$ and $y = 5$. The changes in the variables are:
\begin{align*}
\Delta x &= x - a = 8 - 8 = 0, \\
\Delta y &= y - b = 5 - 3 = 2.
\end{align*}
Substituting these into the linearization equation:
\begin{align*}
f(8, 5) &\approx L(8, 5) \\
&= 24 - 3.4(0) + 4.2(2) \\
&= 24 + 8.4 \\
&= \mathbf{32.4}.
\end{align*}

\subsubsection*{Step 4: Estimate $f(9, 5)$}

Here, we evaluate the function at $x = 9$ and $y = 5$. The changes in the variables are:
\begin{align*}
\Delta x &= x - a = 9 - 8 = 1, \\
\Delta y &= y - b = 5 - 3 = 2.
\end{align*}
Substituting these into the linearization equation:
\begin{align*}
f(9, 5) &\approx L(9, 5) \\
&= 24 - 3.4(1) + 4.2(2) \\
&= 24 - 3.4 + 8.4 \\
&= 20.6 + 8.4 \\
&= \mathbf{29.0}.
\end{align*}

\subsubsection*{Summary of Results}
The estimated values are:
\begin{itemize}
    \item $f(9, 3) \approx 20.6$
    \item $f(8, 5) \approx 32.4$
    \item $f(9, 5) \approx 29.0$
\end{itemize}

