Let $A$ and $B$ be non-empty bounded subsets of $\mathbb{R}$. Then prove that:
    \begin{enumerate}[label=(\roman*)]
      {\item $\inf(A + B) = \inf(A) + \inf(B)$}
      {\item $\sup(A + B) = \sup(A) + \sup(B)$}
    \end{enumerate}

Let $\{a_n\}$ be a sequence of real numbers. Define $s_n = \frac{1}{n} \sum\limits_{i=1}^n a_i$.
    \begin{enumerate}[label=(\roman*)]
      {\item If $\{a_n\}$ is monotone and bounded, show that $\{s_n\}$ is also monotone and bounded.}
      {\item If $\{a_n\} \to a$, then show that $\{s_n\} \to a$.}
    \end{enumerate}

Solution:
To show that the sequences $\{t_n\}$ and $\{s_n\}$ converge to $\max(a, b)$ and $\min(a, b)$ respectively, we utilize the algebraic representations of the maximum and minimum functions.

\begin{proof}
First, recall the following algebraic identities for any real numbers $x$ and $y$:
\begin{align}
    \max(x, y) &= \frac{x + y + |x - y|}{2}, \label{eq:max} \\
    \min(x, y) &= \frac{x + y - |x - y|}{2}. \label{eq:min}
\end{align}
To verify \eqref{eq:max}, consider two cases:
\begin{itemize}
    \item If $x \ge y$, then $|x - y| = x - y$. The right-hand side becomes $\frac{x + y + (x - y)}{2} = \frac{2x}{2} = x$, which is $\max(x, y)$.
    \item If $x < y$, then $|x - y| = -(x - y) = y - x$. The right-hand side becomes $\frac{x + y + (y - x)}{2} = \frac{2y}{2} = y$, which is $\max(x, y)$.
\end{itemize}
A similar verification holds for identity \eqref{eq:min}.

We are given that $\lim_{n\to\infty} a_n = a$ and $\lim_{n\to\infty} b_n = b$. We apply the standard limit laws for sequences.

\begin{enumerate}
    \item \textbf{Limit of the sum and difference:}
    Since $\{a_n\}$ and $\{b_n\}$ are convergent, their sum and difference are convergent:
    \[ \lim_{n\to\infty} (a_n + b_n) = a + b \quad \text{and} \quad \lim_{n\to\infty} (a_n - b_n) = a - b. \]

    \item \textbf{Limit of the absolute value:}
    The absolute value function $f(x) = |x|$ is continuous on $\mathbb{R}$. Therefore, for any convergent sequence $\{c_n\}$ with limit $c$, $\lim_{n\to\infty} |c_n| = |c|$. Applying this to the sequence $\{a_n - b_n\}$:
    \[ \lim_{n\to\infty} |a_n - b_n| = \left| \lim_{n\to\infty} (a_n - b_n) \right| = |a - b|. \]
\end{enumerate}

Now, we determine the limit of the sequence $t_n = \max(a_n, b_n)$. Using identity \eqref{eq:max} and the linearity of limits:
\begin{align*}
    \lim_{n\to\infty} t_n &= \lim_{n\to\infty} \frac{a_n + b_n + |a_n - b_n|}{2} \\
    &= \frac{1}{2} \left(\lim_{n\to\infty} (a_n + b_n) + \lim_{n\to\infty} |a_n - b_n| \right) \\
    &= \frac{1}{2} \left((a + b) + |a - b| \right).
\end{align*}
By the identity \eqref{eq:max} applied to the limits $a$ and $b$, we have:
\[ \frac{a + b + |a - b|}{2} = \max(a, b). \]
Thus, $\lim_{n\to\infty} t_n = \max(a, b)$.

Similarly, for the sequence $s_n = \min(a_n, b_n)$, we use identity \eqref{eq:min}:
\begin{align*}
    \lim_{n\to\infty} s_n &= \lim_{n\to\infty} \frac{a_n + b_n - |a_n - b_n|}{2} \\
    &= \frac{1}{2} \left(\lim_{n\to\infty} (a_n + b_n) - \lim_{n\to\infty} |a_n - b_n| \right) \\
    &= \frac{1}{2} \left((a + b) - |a - b| \right).
\end{align*}
By the identity \eqref{eq:min} applied to $a$ and $b$:
\[ \frac{a + b - |a - b|}{2} = \min(a, b). \]
Thus, $\lim_{n\to\infty} s_n = \min(a, b)$.
\end{proof}

