      {\item $a_1 = 1$, $a_{n+1} = \left(1 + \frac{(-1)^n}{2n}\right)a_n$}
      {\item Given $a, b \in \mathbb{R}$, let $x_1 = a$, $x_2 = b$, and $x_n = \frac{1}{2}(x_{n-1} + x_{n-2})$ for $n \geq 3$}
