Determine if $f'(x)$ is continuous at 0 for the following functions:
  \begin{itemize}
    \item{
      $f(x) =
      \begin{cases}
        x^3 \sin\left(\frac{1}{x}\right), & x \neq 0 \\
        0, & x = 0
      \end{cases}$
    }
    \item{
      $f(x) =
      \begin{cases}
        x^2 \cos\left(\frac{1}{x}\right), & x \neq 0 \\
        0, & x = 0
      \end{cases}$
    }
    \item{
      $f(x) =
      \begin{cases}
        x^2 \ln\left(\frac{1}{|x|}\right), & x \neq 0 \\
        0, & x = 0
      \end{cases}$
    }
  \end{itemize}

Solution:
To determine if the derivative $f'(x)$ is continuous at $x=0$, we must perform the following three steps for each function:
\begin{enumerate}
    \item Find the expression for $f'(x)$ for $x \neq 0$ using standard differentiation rules.
    \item Calculate the value of $f'(0)$ using the limit definition of the derivative.
    \item Evaluate $\lim_{x \to 0} f'(x)$ and check if it equals $f'(0)$.
\end{enumerate}

\begin{enumerate}
    \item \textbf{Function:} $f(x) = \begin{cases} x^3 \sin\left(\frac{1}{x}\right), & x \neq 0 \\ 0, & x = 0 \end{cases}$

    \textbf{Step 1: Derivative for $x \neq 0$.}
    Using the product rule and the chain rule:
    \begin{align*}
        f'(x) &= \frac{d}{dx}\left(x^3 \sin\left(\frac{1}{x}\right) \right) \\
        &= 3x^2 \sin\left(\frac{1}{x}\right) + x^3 \cos\left(\frac{1}{x}\right) \cdot \left(-\frac{1}{x^2}\right) \\
        &= 3x^2 \sin\left(\frac{1}{x}\right) - x \cos\left(\frac{1}{x}\right).
    \end{align*}

    \textbf{Step 2: Derivative at $x = 0$.}
    Using the definition of the derivative:
    \begin{align*}
        f'(0) &= \lim_{h \to 0} \frac{f(0+h) - f(0)}{h} \\
        &= \lim_{h \to 0} \frac{h^3 \sin\left(\frac{1}{h}\right) - 0}{h} \\
        &= \lim_{h \to 0} h^2 \sin\left(\frac{1}{h}\right).
    \end{align*}
    Since $-1 \leq \sin(1/h) \leq 1$, we have $-h^2 \leq h^2 \sin(1/h) \leq h^2$. As $h \to 0$, both $-h^2$ and $h^2$ approach 0. By the Squeeze Theorem, $f'(0) = 0$.

    \textbf{Step 3: Continuity of $f'(x)$ at $x=0$.}
    We examine the limit of $f'(x)$ as $x \to 0$:
    \begin{align*}
        \lim_{x \to 0} f'(x) &= \lim_{x \to 0} \left(3x^2 \sin\left(\frac{1}{x}\right) - x \cos\left(\frac{1}{x}\right) \right).
    \end{align*}
    We analyze the two terms separately using the Squeeze Theorem:
    \begin{itemize}
        \item For the first term: $\lim_{x \to 0} 3x^2 \sin(1/x) = 0$ (bounded sine function multiplied by $x^2 \to 0$).
        \item For the second term: $\lim_{x \to 0} x \cos(1/x) = 0$ (bounded cosine function multiplied by $x \to 0$).
    \end{itemize}
    Thus,
    \[ \lim_{x \to 0} f'(x) = 0 - 0 = 0. \]
    Since $\lim_{x \to 0} f'(x) = 0 = f'(0)$, we conclude that $f'(x)$ is \textbf{continuous} at $x=0$.

    \vspace{0.5cm}

    \item \textbf{Function:} $f(x) = \begin{cases} x^2 \cos\left(\frac{1}{x}\right), & x \neq 0 \\ 0, & x = 0 \end{cases}$

    \textbf{Step 1: Derivative for $x \neq 0$.}
    \begin{align*}
        f'(x) &= \frac{d}{dx}\left(x^2 \cos\left(\frac{1}{x}\right) \right) \\
        &= 2x \cos\left(\frac{1}{x}\right) + x^2 \left(-\sin\left(\frac{1}{x}\right)\right) \cdot \left(-\frac{1}{x^2}\right) \\
        &= 2x \cos\left(\frac{1}{x}\right) + \sin\left(\frac{1}{x}\right).
    \end{align*}

    \textbf{Step 2: Derivative at $x = 0$.}
    \begin{align*}
        f'(0) &= \lim_{h \to 0} \frac{h^2 \cos\left(\frac{1}{h}\right)}{h} \\
        &= \lim_{h \to 0} h \cos\left(\frac{1}{h}\right).
    \end{align*}
    Since $|\cos(1/h)| \leq 1$, we have $|h \cos(1/h)| \leq |h|$. As $h \to 0$, $|h| \to 0$. By the Squeeze Theorem, $f'(0) = 0$.

    \textbf{Step 3: Continuity of $f'(x)$ at $x=0$.}
    We examine the limit:
    \[ \lim_{x \to 0} f'(x) = \lim_{x \to 0} \left(2x \cos\left(\frac{1}{x}\right) + \sin\left(\frac{1}{x}\right) \right). \]
    The first term, $2x \cos(1/x)$, approaches 0 by the Squeeze Theorem. However, the second term, $\sin(1/x)$, oscillates between $-1$ and $1$ as $x \to 0$ and does not approach a unique limit.

    To prove formally that the limit does not exist, consider two sequences approaching 0:
    \begin{itemize}
        \item Let $x_n = \frac{1}{2\pi n}$. Then $\sin(1/x_n) = \sin(2\pi n) = 0 \to 0$.
        \item Let $y_n = \frac{1}{2\pi n + \pi/2}$. Then $\sin(1/y_n) = \sin(2\pi n + \pi/2) = 1 \to 1$.
    \end{itemize}
    Since the limits along different sequences are distinct, $\lim_{x \to 0} \sin(1/x)$ does not exist. Consequently, $\lim_{x \to 0} f'(x)$ does not exist.

    Since the limit does not exist, it cannot equal $f'(0)$. Thus, $f'(x)$ is \textbf{discontinuous} at $x=0$.

    \vspace{0.5cm}

    \item \textbf{Function:} $f(x) = \begin{cases} x^2 \ln\left(\frac{1}{|x|}\right), & x \neq 0 \\ 0, & x = 0 \end{cases}$

    First, simplify the expression for $x \neq 0$ using logarithm properties:
    \[ \ln\left(\frac{1}{|x|}\right) = \ln(|x|^{-1}) = -\ln|x|. \]
    So, $f(x) = -x^2 \ln|x|$ for $x \neq 0$.

    \textbf{Step 1: Derivative for $x \neq 0$.}
    Recall that $\frac{d}{dx} \ln|x| = \frac{1}{x}$.
    \begin{align*}
        f'(x) &= \frac{d}{dx} \left(-x^2 \ln|x| \right) \\
        &= -\left(2x \ln|x| + x^2 \cdot \frac{1}{x} \right) \\
        &= -2x \ln|x| - x.
    \end{align*}

    \textbf{Step 2: Derivative at $x = 0$.}
    \begin{align*}
        f'(0) &= \lim_{h \to 0} \frac{-h^2 \ln|h| - 0}{h} \\
        &= \lim_{h \to 0} -h \ln|h|.
    \end{align*}
    This is an indeterminate form of type $0 \cdot \infty$. We rewrite it to apply L'Hôpital's Rule:
    \begin{align*}
        \lim_{h \to 0} \frac{-\ln|h|}{1/h} \quad \left(\frac{\infty}{\infty}\right) 
        &\stackrel{L'H}{=} \lim_{h \to 0} \frac{-1/h}{-1/h^2} \\
        &= \lim_{h \to 0} \frac{-1}{h} \cdot (-h^2) \\
        &= \lim_{h \to 0} h = 0.
    \end{align*}
    Thus, $f'(0) = 0$.

    \textbf{Step 3: Continuity of $f'(x)$ at $x=0$.}
    We evaluate the limit:
    \begin{align*}
        \lim_{x \to 0} f'(x) &= \lim_{x \to 0} \left(-2x \ln|x| - x \right).
    \end{align*}
    From our calculation in Step 2, we know that $\lim_{x \to 0} x \ln|x| = 0$. Clearly, $\lim_{x \to 0} x = 0$.
    Therefore:
    \[ \lim_{x \to 0} f'(x) = -2(0) - 0 = 0. \]
    Since $\lim_{x \to 0} f'(x) = 0 = f'(0)$, we conclude that $f'(x)$ is \textbf{continuous} at $x=0$.
\end{enumerate}

