Determine which of the following series converges:
  \begin{itemize}
    \item{ $\displaystyle \sum_{n=1}^{\infty} \frac{n 2n!}{(n^3 + 1)n^n}$ }
    \item{ $\displaystyle \sum_{n=1}^{\infty} \frac{\sin(n\pi)}{2^n}$ }
    \item{ $\displaystyle \sum_{n=1}^{\infty} \frac{n(n!)}{(n^2 + 1)(2n+1)!}$ }
  \end{itemize}

Solution:
We evaluate the convergence of each series step by step.

\begin{enumerate}
    \item \textbf{Series 1:} $\displaystyle \sum_{n=1}^{\infty} \frac{n 2n!}{(n^3 + 1)n^n}$

    Let the general term be $a_n = \frac{2n(n!)}{(n^3 + 1)n^n}$. We apply the \textbf{Ratio Test}. We examine the limit $L = \lim_{n \to \infty} \left| \frac{a_{n+1}}{a_n} \right|$.

    \begin{align*}
    L &= \lim_{n \to \infty} \left(\frac{2(n+1)(n+1)!}{((n+1)^3 + 1)(n+1)^{n+1}} \cdot \frac{(n^3 + 1)n^n}{2n(n!)} \right) \\
    &= \lim_{n \to \infty} \left(\frac{2(n+1)}{2n} \cdot \frac{n^3 + 1}{(n+1)^3 + 1} \cdot \frac{(n+1)!}{n!} \cdot \frac{n^n}{(n+1)^{n+1}} \right)
    \end{align*}

    We evaluate the limits of each factor individually:
    \begin{enumerate}
        \item Rational terms: $\lim_{n \to \infty} \frac{n+1}{n} = 1$ and $\lim_{n \to \infty} \frac{n^3 + 1}{(n+1)^3 + 1} = 1$.
        \item Factorial term: $\frac{(n+1)!}{n!} = n+1$.
        \item Exponential term: $\frac{n^n}{(n+1)^{n+1}} = \frac{n^n}{(n+1)(n+1)^n} = \frac{1}{n+1} \left(\frac{n}{n+1}\right)^n$.
    \end{enumerate}

    Substituting these back into the expression for $L$:
    \begin{align*}
    L &= 1 \cdot 1 \cdot \lim_{n \to \infty} \left((n+1) \cdot \frac{1}{n+1} \left(\frac{n}{n+1}\right)^n \right) \\
    &= \lim_{n \to \infty} \left(\frac{n}{n+1} \right)^n \\
    &= \lim_{n \to \infty} \frac{1}{\left(\frac{n+1}{n} \right)^n} \\
    &= \lim_{n \to \infty} \frac{1}{\left(1 + \frac{1}{n} \right)^n}
    \end{align*}

    Recall the standard limit $\lim_{n \to \infty} (1 + \frac{1}{n})^n = e$. Therefore:
    $$ L = \frac{1}{e} $$

    Since $e \approx 2.718$, we have $L = \frac{1}{e} < 1$. By the Ratio Test, the series \textbf{converges}.

    \vspace{0.5cm}

    \item \textbf{Series 2:} $\displaystyle \sum_{n=1}^{\infty} \frac{\sin(n\pi)}{2^n}$

    We analyze the term $a_n = \frac{\sin(n\pi)}{2^n}$.

    Recall that for any integer $n \in \mathbb{Z}$, $\sin(n\pi) = 0$.

    Therefore, for all $n \geq 1$:
    $$ a_n = \frac{0}{2^n} = 0 $$

    The partial sums of the series are:
    $$ S_N = \sum_{n=1}^{N} a_n = \sum_{n=1}^{N} 0 = 0 $$

    Taking the limit of the partial sums:
    $$ \lim_{N \to \infty} S_N = 0 $$

    Thus, the series \textbf{converges} (to 0).

    \vspace{0.5cm}

    \item \textbf{Series 3:} $\displaystyle \sum_{n=1}^{\infty} \frac{n(n!)}{(n^2 + 1)(2n+1)!}$

    Let $a_n = \frac{n(n!)}{(n^2 + 1)(2n+1)!}$. We apply the \textbf{Ratio Test}.

    \begin{align*}
    \left| \frac{a_{n+1}}{a_n} \right| &= \frac{(n+1)(n+1)!}{((n+1)^2 + 1)(2(n+1)+1)!} \cdot \frac{(n^2 + 1)(2n+1)!}{n(n!)} \\
    &= \frac{n+1}{n} \cdot \frac{n^2 + 1}{(n+1)^2 + 1} \cdot \frac{(n+1)!}{n!} \cdot \frac{(2n+1)!}{(2n+3)!}
    \end{align*}

    Simplifying the factorials:
    \begin{itemize}
        \item $\frac{(n+1)!}{n!} = n+1$
        \item $\frac{(2n+1)!}{(2n+3)!} = \frac{(2n+1)!}{(2n+3)(2n+2)(2n+1)!} = \frac{1}{(2n+3)(2n+2)}$
    \end{itemize}

    Substituting these back into the ratio:
    \begin{align*}
    \left| \frac{a_{n+1}}{a_n} \right| &= \left(\frac{n+1}{n} \right) \left(\frac{n^2 + 1}{n^2 + 2n + 2} \right) (n+1) \frac{1}{(2n+3)(2n+2)} \\
    &= \left(\frac{n+1}{n} \right) \left(\frac{n^2 + 1}{n^2 + 2n + 2} \right) \frac{n+1}{(2n+3)2(n+1)} \\
    &= \left(\frac{n+1}{n} \right) \left(\frac{n^2 + 1}{n^2 + 2n + 2} \right) \frac{1}{2(2n+3)}
    \end{align*}

    Now we take the limit as $n \to \infty$:
    \begin{align*}
    L &= \lim_{n \to \infty} \left[ \underbrace{\left(\frac{n+1}{n} \right)}_{\to 1} \underbrace{\left(\frac{n^2 + 1}{n^2 + 2n + 2} \right)}_{\to 1} \underbrace{\frac{1}{4n+6}}_{\to 0} \right] \\
    L &= 1 \cdot 1 \cdot 0 = 0
    \end{align*}

    Since $L = 0 < 1$, by the Ratio Test, the series \textbf{converges}.

\end{enumerate}

\textbf{Conclusion:} All three series converge.

