Solution:
To determine whether a mapping $T: V \rightarrow W$ is a linear transformation over a field $\mathbb{F}$, we must verify two properties for all vectors $u, v \in V$ and all scalars $c \in \mathbb{F}$:
\begin{enumerate}
    \item \textbf{Additivity:} $T(u + v) = T(u) + T(v)$.
    \item \textbf{Homogeneity (Scalar Multiplication):} $T(cu) = cT(u)$.
\end{enumerate}

\begin{enumerate}[label=(\alph*)]
    \item \textbf{Disprove.}

    The mapping $T : \mathbb{C} \rightarrow \mathbb{C}$ defined by $T(z) = \bar{z}$ is \textbf{not} a linear transformation when $\mathbb{C}$ is considered as a vector space over the field of complex numbers $\mathbb{C}$.

    \begin{proof}
    While the map is additive (since $\overline{z_1 + z_2} = \bar{z}_1 + \bar{z}_2$), it fails the property of homogeneity for complex scalars.

    Let $c \in \mathbb{C}$ be a scalar and $z \in \mathbb{C}$ be a vector. The homogeneity condition requires that $T(cz) = cT(z)$.

    Let us evaluate the left-hand side:
    \[
    T(cz) = \overline{cz} = \bar{c}\bar{z}.
    \]
    Now, let us evaluate the right-hand side:
    \[
    cT(z) = c\bar{z}.
    \]
    For $T$ to be linear, we require $\bar{c}\bar{z} = c\bar{z}$ for all $c, z \in \mathbb{C}$. This implies $\bar{c} = c$, which holds only if $c$ is a real number. Since the field of scalars is $\mathbb{C}$, we can choose a non-real scalar to show a contradiction.

    \textbf{Counterexample:}
    Let the scalar be $c = i$ and the vector be $z = 1$.
    \begin{align*}
        T(i \cdot 1) &= T(i) = \bar{i} = -i. \\
        i \cdot T(1) &= i \cdot \bar{1} = i \cdot 1 = i.
    \end{align*}
    Since $-i \neq i$, we have $T(i \cdot 1) \neq i \cdot T(1)$. Thus, $T$ is not linear over $\mathbb{C}$.
    \end{proof}

    \item \textbf{Prove.}

    The mapping $T : \mathbb{R}[x] \rightarrow \mathbb{R}[x]$ defined by $T(p(x)) = x^2p(x) + p(1)$ is a linear transformation.

    \begin{proof}
    Let $p(x), q(x) \in \mathbb{R}[x]$ be arbitrary polynomials and let $\alpha \in \mathbb{R}$ be an arbitrary scalar.

    \textbf{1. Additivity:}
    We evaluate $T$ on the sum of the polynomials:
    \begin{align*}
        T(p(x) + q(x)) &= x^2(p(x) + q(x)) + (p + q)(1) \\
        &= x^2(p(x) + q(x)) + (p(1) + q(1)) \\
        &= x^2p(x) + x^2q(x) + p(1) + q(1).
    \end{align*}
    Rearranging the terms, we obtain:
    \begin{align*}
        T(p(x) + q(x)) &= (x^2p(x) + p(1)) + (x^2q(x) + q(1)) \\
        &= T(p(x)) + T(q(x)).
    \end{align*}
    Thus, additivity holds.

    \textbf{2. Homogeneity:}
    We evaluate $T$ on the scalar multiple of a polynomial:
    \begin{align*}
        T(\alpha p(x)) &= x^2(\alpha p(x)) + (\alpha p)(1) \\
        &= \alpha x^2 p(x) + \alpha p(1) \\
        &= \alpha (x^2 p(x) + p(1)) \\
        &= \alpha T(p(x)).
    \end{align*}
    Thus, homogeneity holds.

    Since both conditions are satisfied, $T$ is a linear transformation.
    \end{proof}
\end{enumerate}

