latexcode:
Solve the following initial value problems:
    \begin{itemize}
        \item{$x^2 y'' - 2x y' + 2y = 0$, $y(1) = 1.5$, $y'(1) = 1$}
        \item{$x^2 y'' + 3x y' + y = 0$, $y(1) = 3$, $y'(1) = -4$}
        \item{$x^2 y'' - 3x y' + 4y = 0$, $y(1) = 0$, $y'(1) = 3$}
    \end{itemize}

Use the variation of parameters method to solve:
    \begin{itemize}
        \item{$y'' + 9y = \csc(3x)$}
        \item{$x^2 y'' - 2x y' + 2y = x^3 \sin x$}
        \item{$y'' - 4y' + 4y = \frac{6e^{2x}}{x^4}$}
    \end{itemize}

Solution:
The equation of motion for a forced mass-spring-damper system is given by the second-order linear differential equation with constant coefficients:
\begin{equation*}
    mx'' + cx' + kx = F(t).
\end{equation*}
Given the parameters $m = 1$, $c = 4$, $k = 24$, and the forcing function $F(t) = 10 \cos(\omega t)$, the specific differential equation becomes:
\begin{equation*}
    x'' + 4x' + 24x = 10 \cos(\omega t).
\end{equation*}

We proceed in three steps: determining the frequency $\omega$ that maximizes the steady-state amplitude, computing that maximum amplitude, and finding the general solution for the system at that specific frequency.

\begin{enumerate}[label=\textbf{\arabic*.}]
    \item \textbf{Determination of $\omega$ for Maximum Amplitude}

    The steady-state particular solution $x_p(t)$ for a sinusoidal forcing function $F(t) = F_0 \cos(\omega t)$ takes the form $x_p(t) = C(\omega) \cos(\omega t - \delta)$. The amplitude $C(\omega)$ is given by the formula:
    \begin{equation*}
        C(\omega) = \frac{F_0}{\sqrt{(k - m\omega^2)^2 + (c\omega)^2}}.
    \end{equation*}
    Substituting the given values $F_0 = 10$, $m=1$, $c=4$, and $k=24$:
    \begin{equation*}
        C(\omega) = \frac{10}{\sqrt{(24 - \omega^2)^2 + (4\omega)^2}}.
    \end{equation*}
    To maximize $C(\omega)$, we must minimize the denominator. Let $g(\omega)$ be the quantity inside the square root:
    \begin{equation*}
        g(\omega) = (24 - \omega^2)^2 + 16\omega^2.
    \end{equation*}
    To find the critical points, we differentiate $g(\omega)$ with respect to $\omega$ and set the derivative to zero:
    \begin{align*}
        g'(\omega) &= 2(24 - \omega^2)(-2\omega) + 32\omega \\
        &= -4\omega(24 - \omega^2) + 32\omega \\
        &= -96\omega + 4\omega^3 + 32\omega \\
        &= 4\omega^3 - 64\omega \\
        &= 4\omega(\omega^2 - 16).
    \end{align*}
    Setting $g'(\omega) = 0$, we find roots at $\omega = 0$ and $\omega = \pm 4$. Since $\omega$ represents a physical frequency, we consider $\omega > 0$. Thus, the frequency that maximizes the amplitude is:
    \begin{equation*}
        \boxed{\omega = 4}.
    \end{equation*}
    (Note: This corresponds to the practical resonance frequency formula $\omega_r = \sqrt{\frac{k}{m} - \frac{c^2}{2m^2}} = \sqrt{24 - \frac{16}{2}} = \sqrt{16} = 4$).

    \item \textbf{Computation of the Maximum Amplitude}

    We evaluate the amplitude function $C(\omega)$ at $\omega = 4$:
    \begin{align*}
        C(4) &= \frac{10}{\sqrt{(24 - 4^2)^2 + (4 \cdot 4)^2}} \\
        &= \frac{10}{\sqrt{(24 - 16)^2 + 16^2}} \\
        &= \frac{10}{\sqrt{8^2 + 16^2}} \\
        &= \frac{10}{\sqrt{64 + 256}} \\
        &= \frac{10}{\sqrt{320}}.
    \end{align*}
    Simplifying the radical $\sqrt{320} = \sqrt{64 \cdot 5} = 8\sqrt{5}$:
    \begin{equation*}
        C_{max} = \frac{10}{8\sqrt{5}} = \frac{5}{4\sqrt{5}} = \frac{\sqrt{5}}{4}.
    \end{equation*}
    The maximum amplitude is:
    \begin{equation*}
        \boxed{C_{max} = \frac{\sqrt{5}}{4}}.
    \end{equation*}

    \item \textbf{General Solution}

    With $\omega = 4$, the differential equation is:
    \begin{equation*}
        x'' + 4x' + 24x = 10 \cos(4t).
    \end{equation*}
    The general solution is the sum of the homogeneous solution $x_h(t)$ and the particular solution $x_p(t)$.

    \textbf{Homogeneous Solution:}
    We solve the associated homogeneous equation $x'' + 4x' + 24x = 0$. The characteristic equation is:
    \begin{equation*}
        r^2 + 4r + 24 = 0.
    \end{equation*}
    Using the quadratic formula:
    \begin{equation*}
        r = \frac{-4 \pm \sqrt{16 - 4(24)}}{2} = \frac{-4 \pm \sqrt{16 - 96}}{2} = \frac{-4 \pm \sqrt{-80}}{2}.
    \end{equation*}
    Since $\sqrt{-80} = i\sqrt{16 \cdot 5} = 4i\sqrt{5}$, the roots are:
    \begin{equation*}
        r = -2 \pm 2i\sqrt{5}.
    \end{equation*}
    Thus, the homogeneous solution is:
    \begin{equation*}
        x_h(t) = e^{-2t} \left(c_1 \cos(2\sqrt{5}t) + c_2 \sin(2\sqrt{5}t) \right).
    \end{equation*}

    \textbf{Particular Solution:}
    We use the Method of Undetermined Coefficients. We assume a solution of the form:
    \begin{equation*}
        x_p(t) = A \cos(4t) + B \sin(4t).
    \end{equation*}
    Computing the derivatives:
    \begin{align*}
        x_p'(t) &= -4A \sin(4t) + 4B \cos(4t), \\
        x_p''(t) &= -16A \cos(4t) - 16B \sin(4t).
    \end{align*}
    Substituting these into the differential equation $x'' + 4x' + 24x = 10 \cos(4t)$:
    \begin{multline*}
        (-16A \cos(4t) - 16B \sin(4t)) + 4(-4A \sin(4t) + 4B \cos(4t)) \\ + 24(A \cos(4t) + B \sin(4t)) = 10 \cos(4t).
    \end{multline*}
    Grouping the cosine and sine terms:
    \begin{align*}
        \cos(4t) [-16A + 16B + 24A] + \sin(4t) [-16B - 16A + 24B] &= 10 \cos(4t) \\
        \cos(4t) [8A + 16B] + \sin(4t) [-16A + 8B] &= 10 \cos(4t).
    \end{align*}
    Equating coefficients gives the system of linear equations:
    \begin{align}
        8A + 16B &= 10, \label{eq:1} \\
        -16A + 8B &= 0. \label{eq:2}
    \end{align}
    From equation (\ref{eq:2}), we have $16A = 8B \implies B = 2A$. Substituting this into equation (\ref{eq:1}):
    \begin{align*}
        8A + 16(2A) &= 10 \\
        8A + 32A &= 10 \\
        40A &= 10 \implies A = \frac{1}{4}.
    \end{align*}
    Then, $B = 2\left(\frac{1}{4}\right) = \frac{1}{2}$.

    The particular solution is:
    \begin{equation*}
        x_p(t) = \frac{1}{4} \cos(4t) + \frac{1}{2} \sin(4t).
    \end{equation*}
    (Check amplitude: $\sqrt{(1/4)^2 + (1/2)^2} = \sqrt{1/16 + 4/16} = \sqrt{5}/4$, which matches our previous calculation).

    \textbf{Conclusion:}
    Combining $x_h(t)$ and $x_p(t)$, the general solution is:
    \begin{equation*}
        \boxed{x(t) = e^{-2t} \left(c_1 \cos(2\sqrt{5}t) + c_2 \sin(2\sqrt{5}t) \right) + \frac{1}{4} \cos(4t) + \frac{1}{2} \sin(4t)}.
    \end{equation*}
\end{enumerate}

