    \item{$e^{-\alpha t} \cos \beta t$.}
    \end{enumerate}

Find the inverse Laplace transforms of:
    \begin{itemize}
        \item{$\frac{5s}{s^2 - 25}$}
        \item{$\frac{1 - 7s}{(s - 3)(s - 1)(s + 2)}$}
        \item{$\frac{2s^3}{s^4 - 1}$}
        \item{$\frac{2}{s^2 + s + \frac{1}{2}}$}
    \end{itemize}

Solve using Laplace transform:
    \begin{itemize}
        \item{$y'' - y' - 2y = 0$, $y(0) = 8$, $y'(0) = 7$}
        \item{$y'' + 2y' - 3y = 6e^{-2t}$, $y(0) = 2$, $y'(0) = -14$}
    \end{itemize}

Find the Laplace transforms of: 
    \begin{enumerate}
    \item{$tu(t-1)$}
    \item{$e^{-2t} u(t-3)$}
    \item{$4u(t - \pi) \cos t$.}
    \end{enumerate}

Solution:
To find the Laplace transforms of the given functions, we utilize the **Second Shifting Theorem** (also known as the $t$-shifting property).

\textbf{Theorem (Second Shifting Property):}
If $\mathcal{L}\{f(t)\} = F(s)$ and $u(t-a)$ is the Heaviside unit step function where $a > 0$, then:
\begin{equation*}
    \mathcal{L}\{u(t-a)g(t)\} = e^{-as}\mathcal{L}\{g(t+a)\}.
\end{equation*}
Alternatively, if the function is already in the form $g(t-a)$, the property is:
\begin{equation*}
    \mathcal{L}\{u(t-a)g(t-a)\} = e^{-as}G(s), \quad \text{where } G(s) = \mathcal{L}\{g(t)\}.
\end{equation*}

We will apply these properties to each problem.

\begin{enumerate}
    \item \textbf{Find the Laplace transform of $t u(t-1)$.}

    Here, we have a function of the form $u(t-a)g(t)$ with $a=1$ and $g(t) = t$.
    Using the property $\mathcal{L}\{u(t-a)g(t)\} = e^{-as}\mathcal{L}\{g(t+a)\}$, we proceed as follows:

    1. Identify the shift $a = 1$.
    2. Determine $g(t+a)$. Since $g(t) = t$, we have:
       \[ g(t+1) = t + 1. \]
    3. Compute the transform:
    \begin{align*}
        \mathcal{L}\{t u(t-1)\} &= e^{-1s} \mathcal{L}\{t + 1\} \\
        &= e^{-s} \left(\mathcal{L}\{t\} + \mathcal{L}\{1\} \right).
    \end{align*}
    Recall the standard transforms $\mathcal{L}\{t\} = \frac{1}{s^2}$ and $\mathcal{L}\{1\} = \frac{1}{s}$. Substituting these yields:
    \begin{align*}
        \mathcal{L}\{t u(t-1)\} &= e^{-s} \left(\frac{1}{s^2} + \frac{1}{s} \right) \\
        &= \frac{e^{-s}(1+s)}{s^2}.
    \end{align*}

    \item \textbf{Find the Laplace transform of $e^{-2t} u(t-3)$.}

    Here, $a=3$ and $g(t) = e^{-2t}$. We apply the property $\mathcal{L}\{u(t-3)g(t)\} = e^{-3s}\mathcal{L}\{g(t+3)\}$.

    1. Determine $g(t+3)$:
       \[ g(t+3) = e^{-2(t+3)} = e^{-2t - 6} = e^{-6}e^{-2t}. \]
    2. Compute the transform:
    \begin{align*}
        \mathcal{L}\{e^{-2t} u(t-3)\} &= e^{-3s} \mathcal{L}\{e^{-6}e^{-2t}\} \\
        &= e^{-3s} e^{-6} \mathcal{L}\{e^{-2t}\}.
    \end{align*}
    Recall that $\mathcal{L}\{e^{kt}\} = \frac{1}{s-k}$. Thus, $\mathcal{L}\{e^{-2t}\} = \frac{1}{s+2}$.
    \begin{align*}
        \mathcal{L}\{e^{-2t} u(t-3)\} &= e^{-3s} e^{-6} \left(\frac{1}{s+2} \right) \\
        &= \frac{e^{-(3s+6)}}{s+2}.
    \end{align*}

    \item \textbf{Find the Laplace transform of $4u(t - \pi) \cos t$.}

    Here, $a=\pi$ and $g(t) = 4\cos t$. We apply the property $\mathcal{L}\{u(t-\pi)g(t)\} = e^{-\pi s}\mathcal{L}\{g(t+\pi)\}$.

    1. Determine $g(t+\pi)$:
       \[ g(t+\pi) = 4\cos(t + \pi). \]
       Using the trigonometric identity $\cos(t + \pi) = -\cos t$, we get:
       \[ g(t+\pi) = -4\cos t. \]
    2. Compute the transform:
    \begin{align*}
        \mathcal{L}\{4u(t - \pi) \cos t\} &= e^{-\pi s} \mathcal{L}\{-4\cos t\} \\
        &= -4e^{-\pi s} \mathcal{L}\{\cos t\}.
    \end{align*}
    Recall that $\mathcal{L}\{\cos \omega t\} = \frac{s}{s^2 + \omega^2}$. With $\omega = 1$:
    \begin{align*}
        \mathcal{L}\{4u(t - \pi) \cos t\} &= -4e^{-\pi s} \left(\frac{s}{s^2 + 1} \right) \\
        &= -\frac{4s e^{-\pi s}}{s^2 + 1}.
    \end{align*}
\end{enumerate}

