Use the definition to find the derivative of each of the following functions:
    \begin{itemize}
        \item{$f(x) := x^3$, for $x \in \mathbb{R}$}
        \item{$g(x) := \frac{1}{x}$, for $x \in \mathbb{R},\, x \neq 0$}
        \item{$h(x) := \sqrt{x}$, for $x > 0$}
        \item{$k(x) := \frac{1}{\sqrt{x}}$, for $x > 0$}
    \end{itemize}

Solution:
To find the derivative of a function $f$ at a point $x$, we use the limit definition of the derivative:
\[
f'(x) = \lim_{h \to 0} \frac{f(x+h) - f(x)}{h}.
\]
We will apply this definition to each of the given functions.

\begin{enumerate}
    \item \textbf{Function:} $f(x) = x^3$ for $x \in \mathbb{R}$.

    We substitute $f(x) = x^3$ into the definition:
    \begin{align*}
        f'(x) &= \lim_{h \to 0} \frac{(x+h)^3 - x^3}{h}.
    \end{align*}
    First, we expand the term $(x+h)^3$ using the binomial theorem (or algebraic expansion):
    \[
    (x+h)^3 = x^3 + 3x^2h + 3xh^2 + h^3.
    \]
    Substituting this back into the limit:
    \begin{align*}
        f'(x) &= \lim_{h \to 0} \frac{(x^3 + 3x^2h + 3xh^2 + h^3) - x^3}{h} \\
        &= \lim_{h \to 0} \frac{3x^2h + 3xh^2 + h^3}{h}.
    \end{align*}
    Since $h$ approaches 0 but is not equal to 0, we can factor $h$ out of the numerator and cancel it with the denominator:
    \begin{align*}
        f'(x) &= \lim_{h \to 0} \frac{h(3x^2 + 3xh + h^2)}{h} \\
        &= \lim_{h \to 0} (3x^2 + 3xh + h^2).
    \end{align*}
    Finally, we evaluate the limit by setting $h = 0$:
    \[
    f'(x) = 3x^2 + 3x(0) + (0)^2 = 3x^2.
    \]

    \item \textbf{Function:} $g(x) = \frac{1}{x}$ for $x \in \mathbb{R}, \, x \neq 0$.

    We substitute $g(x) = \frac{1}{x}$ into the definition:
    \begin{align*}
        g'(x) &= \lim_{h \to 0} \frac{\frac{1}{x+h} - \frac{1}{x}}{h}.
    \end{align*}
    To simplify the complex fraction, we find a common denominator for the numerator terms, which is $x(x+h)$:
    \begin{align*}
        g'(x) &= \lim_{h \to 0} \frac{\frac{x - (x+h)}{x(x+h)}}{h} \\
        &= \lim_{h \to 0} \frac{x - x - h}{h \cdot x(x+h)} \\
        &= \lim_{h \to 0} \frac{-h}{h x(x+h)}.
    \end{align*}
    Canceling the factor $h$ (where $h \neq 0$):
    \begin{align*}
        g'(x) &= \lim_{h \to 0} \frac{-1}{x(x+h)}.
    \end{align*}
    Evaluating the limit as $h \to 0$:
    \[
    g'(x) = \frac{-1}{x(x+0)} = -\frac{1}{x^2}.
    \]

    \item \textbf{Function:} $h(x) = \sqrt{x}$ for $x > 0$.

    We substitute $h(x) = \sqrt{x}$ into the definition:
    \begin{align*}
        h'(x) &= \lim_{k \to 0} \frac{\sqrt{x+k} - \sqrt{x}}{k}.
    \end{align*}
    (Note: We use $k$ here as the increment variable to avoid confusion with the function name $h$, though the logic remains identical).

    Direct substitution yields the indeterminate form $\frac{0}{0}$. To resolve this, we rationalize the numerator by multiplying the numerator and the denominator by the conjugate expression $\sqrt{x+k} + \sqrt{x}$:
    \begin{align*}
        h'(x) &= \lim_{k \to 0} \left(\frac{\sqrt{x+k} - \sqrt{x}}{k} \cdot \frac{\sqrt{x+k} + \sqrt{x}}{\sqrt{x+k} + \sqrt{x}} \right) \\
        &= \lim_{k \to 0} \frac{(\sqrt{x+k})^2 - (\sqrt{x})^2}{k(\sqrt{x+k} + \sqrt{x})} \\
        &= \lim_{k \to 0} \frac{(x+k) - x}{k(\sqrt{x+k} + \sqrt{x})} \\
        &= \lim_{k \to 0} \frac{k}{k(\sqrt{x+k} + \sqrt{x})}.
    \end{align*}
    Canceling $k$:
    \begin{align*}
        h'(x) &= \lim_{k \to 0} \frac{1}{\sqrt{x+k} + \sqrt{x}}.
    \end{align*}
    Evaluating the limit as $k \to 0$:
    \[
    h'(x) = \frac{1}{\sqrt{x+0} + \sqrt{x}} = \frac{1}{2\sqrt{x}}.
    \]

    \item \textbf{Function:} $k(x) = \frac{1}{\sqrt{x}}$ for $x > 0$.

    We substitute $k(x) = \frac{1}{\sqrt{x}}$ into the definition:
    \begin{align*}
        k'(x) &= \lim_{h \to 0} \frac{\frac{1}{\sqrt{x+h}} - \frac{1}{\sqrt{x}}}{h}.
    \end{align*}
    First, combine the fractions in the numerator using the common denominator $\sqrt{x}\sqrt{x+h}$:
    \begin{align*}
        k'(x) &= \lim_{h \to 0} \frac{\frac{\sqrt{x} - \sqrt{x+h}}{\sqrt{x}\sqrt{x+h}}}{h} \\
        &= \lim_{h \to 0} \frac{\sqrt{x} - \sqrt{x+h}}{h\sqrt{x}\sqrt{x+h}}.
    \end{align*}
    Next, we rationalize the numerator by multiplying by the conjugate $\sqrt{x} + \sqrt{x+h}$:
    \begin{align*}
        k'(x) &= \lim_{h \to 0} \left(\frac{\sqrt{x} - \sqrt{x+h}}{h\sqrt{x}\sqrt{x+h}} \cdot \frac{\sqrt{x} + \sqrt{x+h}}{\sqrt{x} + \sqrt{x+h}} \right) \\
        &= \lim_{h \to 0} \frac{x - (x+h)}{h\sqrt{x}\sqrt{x+h}(\sqrt{x} + \sqrt{x+h})} \\
        &= \lim_{h \to 0} \frac{-h}{h\sqrt{x}\sqrt{x+h}(\sqrt{x} + \sqrt{x+h})}.
    \end{align*}
    Canceling $h$:
    \begin{align*}
        k'(x) &= \lim_{h \to 0} \frac{-1}{\sqrt{x}\sqrt{x+h}(\sqrt{x} + \sqrt{x+h})}.
    \end{align*}
    Evaluating the limit as $h \to 0$:
    \begin{align*}
        k'(x) &= \frac{-1}{\sqrt{x}\sqrt{x}(\sqrt{x} + \sqrt{x})} \\
        &= \frac{-1}{x(2\sqrt{x})} \\
        &= -\frac{1}{2x\sqrt{x}} \quad \text{or} \quad -\frac{1}{2}x^{-3/2}.
    \end{align*}
\end{enumerate}

