Let $f : \mathbb{R} \to \mathbb{R}$ be defined by
    \[
    f(x) := 
    \begin{cases}
        x^2, & \text{if } x \in \mathbb{Q} \\
        0,   & \text{if } x \notin \mathbb{Q}
    \end{cases}
    \]
    Show that $f$ is differentiable at $x = 0$, and find $f'(0)$.

Differentiate and simplify:
    \begin{itemize}
        \item{$f(x) := \frac{x}{1 + x^2}$}
        \item{$g(x) := \sqrt{5 - 2x + x^2}$}
        \item{$h(x) := (\sin x^k)^m$, where $m, k \in \mathbb{N}$}
        \item{$k(x) := \tan(x^2)$, for $|x| < \sqrt{\pi/2}$}
    \end{itemize}

Determine where each of the following functions $f : \mathbb{R} \to \mathbb{R}$ is differentiable and find the derivative:
    \begin{itemize}
        \item{$f(x) := |x| + |x + 1|$}
        \item{$g(x) := 2x + |x|$}
        \item{$h(x) := x |x|$}
        \item{$k(x) := |\sin x|$}
    \end{itemize}

For each of the following functions $f : \mathbb{R} \to \mathbb{R}$, find points of relative extrema, the intervals on which the function is increasing, and those on which it is decreasing:
    \begin{itemize}
        \item{$f(x) := x^2 - 3x + 5$}
        \item{$g(x) := 3x - 4x^2$}
        \item{$h(x) := x^3 - 3x - 4$}
        \item{$k(x) := x^4 + 2x^2 - 4$}
    \end{itemize}

Solution:
\noindent To determine the intervals of monotonicity and the relative extrema for the given functions, we utilize the First Derivative Test. For a differentiable function $f: \mathbb{R} \to \mathbb{R}$:
\begin{itemize}
    \item If $f'(x) > 0$ on an interval, $f$ is strictly increasing on that interval.
    \item If $f'(x) < 0$ on an interval, $f$ is strictly decreasing on that interval.
    \item Critical points occur where $f'(x) = 0$ or where $f'(x)$ is undefined. Since all functions provided are polynomials, they are differentiable everywhere on $\mathbb{R}$; thus, we only seek solutions to $f'(x) = 0$.
\end{itemize}

\begin{enumerate}[label=(\alph*)]
    % Function 1
    \item \textbf{Analysis of} $f(x) := x^2 - 3x + 5$

    First, we compute the derivative with respect to $x$:
    \begin{align*}
        f'(x) = \frac{d}{dx}(x^2 - 3x + 5) = 2x - 3.
    \end{align*}
    To find the critical points, we set $f'(x) = 0$:
    \begin{align*}
        2x - 3 = 0 \implies x = \frac{3}{2}.
    \end{align*}
    We analyze the sign of $f'(x)$ on the intervals determined by the critical point $x = \frac{3}{2}$:
    \begin{itemize}
        \item On the interval $\left(-\infty, \frac{3}{2}\right)$, choose a test point $x = 0$. Then $f'(0) = -3 < 0$. Thus, $f$ is \textbf{decreasing}.
        \item On the interval $\left(\frac{3}{2}, \infty\right)$, choose a test point $x = 2$. Then $f'(2) = 1 > 0$. Thus, $f$ is \textbf{increasing}.
    \end{itemize}

    By the First Derivative Test, since $f'(x)$ changes sign from negative to positive at $x = \frac{3}{2}$, there is a relative minimum at this point. The value of the minimum is:
    \[ f\left(\frac{3}{2}\right) = \left(\frac{3}{2}\right)^2 - 3\left(\frac{3}{2}\right) + 5 = \frac{9}{4} - \frac{18}{4} + \frac{20}{4} = \frac{11}{4}. \]

    \textbf{Summary for} $f$:
    \begin{itemize}
        \item Increasing on: $\left(\frac{3}{2}, \infty\right)$
        \item Decreasing on: $\left(-\infty, \frac{3}{2}\right)$
        \item Relative Minimum: $\left(\frac{3}{2}, \frac{11}{4}\right)$
        \item Relative Maximum: None
    \end{itemize}

    % Function 2
    \item \textbf{Analysis of} $g(x) := 3x - 4x^2$

    Compute the derivative:
    \begin{align*}
        g'(x) = 3 - 8x.
    \end{align*}
    Set $g'(x) = 0$ to find critical points:
    \begin{align*}
        3 - 8x = 0 \implies x = \frac{3}{8}.
    \end{align*}
    Analyze the sign of $g'(x)$:
    \begin{itemize}
        \item On $\left(-\infty, \frac{3}{8}\right)$, choose $x = 0$. Then $g'(0) = 3 > 0$. Thus, $g$ is \textbf{increasing}.
        \item On $\left(\frac{3}{8}, \infty\right)$, choose $x = 1$. Then $g'(1) = 3 - 8 = -5 < 0$. Thus, $g$ is \textbf{decreasing}.
    \end{itemize}

    Since $g'(x)$ changes from positive to negative at $x = \frac{3}{8}$, there is a relative maximum. The value is:
    \[ g\left(\frac{3}{8}\right) = 3\left(\frac{3}{8}\right) - 4\left(\frac{3}{8}\right)^2 = \frac{9}{8} - 4\left(\frac{9}{64}\right) = \frac{18}{16} - \frac{9}{16} = \frac{9}{16}. \]

    \textbf{Summary for} $g$:
    \begin{itemize}
        \item Increasing on: $\left(-\infty, \frac{3}{8}\right)$
        \item Decreasing on: $\left(\frac{3}{8}, \infty\right)$
        \item Relative Maximum: $\left(\frac{3}{8}, \frac{9}{16}\right)$
        \item Relative Minimum: None
    \end{itemize}

    % Function 3
    \item \textbf{Analysis of} $h(x) := x^3 - 3x - 4$

    Compute the derivative:
    \begin{align*}
        h'(x) = 3x^2 - 3.
    \end{align*}
    Set $h'(x) = 0$:
    \begin{align*}
        3(x^2 - 1) = 0 \implies (x-1)(x+1) = 0.
    \end{align*}
    The critical points are $x = -1$ and $x = 1$. These points divide the domain into three intervals:
    \begin{itemize}
        \item On $(-\infty, -1)$, choose $x = -2$. Then $h'(-2) = 3(4) - 3 = 9 > 0$. ($h$ is \textbf{increasing}).
        \item On $(-1, 1)$, choose $x = 0$. Then $h'(0) = -3 < 0$. ($h$ is \textbf{decreasing}).
        \item On $(1, \infty)$, choose $x = 2$. Then $h'(2) = 3(4) - 3 = 9 > 0$. ($h$ is \textbf{increasing}).
    \end{itemize}

    \textbf{Extrema Analysis:}
    \begin{itemize}
        \item At $x = -1$, the sign of $h'$ changes from positive to negative. This indicates a relative maximum.
        \[ h(-1) = (-1)^3 - 3(-1) - 4 = -1 + 3 - 4 = -2. \]
        \item At $x = 1$, the sign of $h'$ changes from negative to positive. This indicates a relative minimum.
        \[ h(1) = (1)^3 - 3(1) - 4 = 1 - 3 - 4 = -6. \]
    \end{itemize}

    \textbf{Summary for} $h$:
    \begin{itemize}
        \item Increasing on: $(-\infty, -1)$ and $(1, \infty)$
        \item Decreasing on: $(-1, 1)$
        \item Relative Maximum: $(-1, -2)$
        \item Relative Minimum: $(1, -6)$
    \end{itemize}

    % Function 4
    \item \textbf{Analysis of} $k(x) := x^4 + 2x^2 - 4$

    Compute the derivative:
    \begin{align*}
        k'(x) = 4x^3 + 4x.
    \end{align*}
    Set $k'(x) = 0$ and factor:
    \begin{align*}
        4x(x^2 + 1) = 0.
    \end{align*}
    Since $x^2 + 1 \geq 1$ for all $x \in \mathbb{R}$, the term $(x^2+1)$ is never zero. Therefore, the only critical point is $x = 0$.

    We analyze the sign of $k'(x)$ around $x=0$:
    \begin{itemize}
        \item On $(-\infty, 0)$, choose $x = -1$. Note that $x^2+1$ is always positive, so the sign depends only on $4x$. Thus, $k'(-1) = 4(-1)(2) = -8 < 0$. ($k$ is \textbf{decreasing}).
        \item On $(0, \infty)$, choose $x = 1$. Then $k'(1) = 4(1)(2) = 8 > 0$. ($k$ is \textbf{increasing}).
    \end{itemize}

    Since $k'(x)$ changes from negative to positive at $x = 0$, there is a relative minimum.
    \[ k(0) = 0^4 + 2(0)^2 - 4 = -4. \]

    \textbf{Summary for} $k$:
    \begin{itemize}
        \item Increasing on: $(0, \infty)$
        \item Decreasing on: $(-\infty, 0)$
        \item Relative Minimum: $(0, -4)$
        \item Relative Maximum: None
    \end{itemize}
\end{enumerate}

