latexcode:
Find all the second order partial derivatives:
    \begin{itemize}
        \item{$g(x, y) = x^2 y + \cos y + y \sin x$}
        \item{$g(x, y) = \tan^{-1}(y/x)$}
    \end{itemize}

Solution:
To find the second-order partial derivatives of a function $g(x, y)$, we must first determine the first-order partial derivatives with respect to $x$ and $y$. The second-order derivatives are then found by differentiating the first-order derivatives again.

The four second-order partial derivatives are denoted as:
\[
g_{xx} = \frac{\partial^2 g}{\partial x^2}, \quad g_{yy} = \frac{\partial^2 g}{\partial y^2}, \quad g_{xy} = \frac{\partial^2 g}{\partial y \partial x}, \quad \text{and} \quad g_{yx} = \frac{\partial^2 g}{\partial x \partial y}.
\]

\begin{enumerate}
    \item \textbf{Function:} $g(x, y) = x^2 y + \cos y + y \sin x$

    \textbf{Step 1: First-order partial derivatives.}

    To find $g_x$, we differentiate with respect to $x$ while treating $y$ as a constant:
    \begin{align*}
        g_x(x, y) &= \frac{\partial}{\partial x}(x^2 y) + \frac{\partial}{\partial x}(\cos y) + \frac{\partial}{\partial x}(y \sin x) \\
        &= 2xy + 0 + y \cos x \\
        &= 2xy + y \cos x.
    \end{align*}

    To find $g_y$, we differentiate with respect to $y$ while treating $x$ as a constant:
    \begin{align*}
        g_y(x, y) &= \frac{\partial}{\partial y}(x^2 y) + \frac{\partial}{\partial y}(\cos y) + \frac{\partial}{\partial y}(y \sin x) \\
        &= x^2 - \sin y + \sin x.
    \end{align*}

    \textbf{Step 2: Second-order partial derivatives.}

    Now we differentiate the results from Step 1.

    For $g_{xx}$, differentiate $g_x$ with respect to $x$:
    \begin{align*}
        g_{xx} &= \frac{\partial}{\partial x}(2xy + y \cos x) \\
        &= 2y + y(-\sin x) \\
        &= 2y - y \sin x.
    \end{align*}

    For $g_{yy}$, differentiate $g_y$ with respect to $y$:
    \begin{align*}
        g_{yy} &= \frac{\partial}{\partial y}(x^2 - \sin y + \sin x) \\
        &= 0 - \cos y + 0 \\
        &= -\cos y.
    \end{align*}

    For the mixed partial derivative $g_{xy}$, differentiate $g_x$ with respect to $y$:
    \begin{align*}
        g_{xy} &= \frac{\partial}{\partial y}(2xy + y \cos x) \\
        &= 2x + \cos x.
    \end{align*}

    For the mixed partial derivative $g_{yx}$, differentiate $g_y$ with respect to $x$:
    \begin{align*}
        g_{yx} &= \frac{\partial}{\partial x}(x^2 - \sin y + \sin x) \\
        &= 2x - 0 + \cos x \\
        &= 2x + \cos x.
    \end{align*}

    \textit{Note: As expected for continuous functions, $g_{xy} = g_{yx}$ (Clairaut's Theorem).}

    \item \textbf{Function:} $g(x, y) = \tan^{-1}\left(\frac{y}{x}\right)$

    \textbf{Step 1: First-order partial derivatives.}

    Recall the derivative of the arctangent function: $\frac{d}{du} \tan^{-1}(u) = \frac{1}{1+u^2} \frac{du}{dx}$.

    To find $g_x$, we apply the chain rule with respect to $x$:
    \begin{align*}
        g_x(x, y) &= \frac{1}{1 + \left(\frac{y}{x}\right)^2} \cdot \frac{\partial}{\partial x}\left(y x^{-1}\right) \\
        &= \frac{1}{1 + \frac{y^2}{x^2}} \cdot \left(-y x^{-2}\right) \\
        &= \frac{x^2}{x^2 + y^2} \cdot \frac{-y}{x^2} \\
        &= \frac{-y}{x^2 + y^2}.
    \end{align*}

    To find $g_y$, we apply the chain rule with respect to $y$:
    \begin{align*}
        g_y(x, y) &= \frac{1}{1 + \left(\frac{y}{x}\right)^2} \cdot \frac{\partial}{\partial y}\left(\frac{y}{x}\right) \\
        &= \frac{x^2}{x^2 + y^2} \cdot \frac{1}{x} \\
        &= \frac{x}{x^2 + y^2}.
    \end{align*}

    \textbf{Step 2: Second-order partial derivatives.}

    For $g_{xx}$, differentiate $g_x = -y(x^2+y^2)^{-1}$ with respect to $x$. Using the chain rule:
    \begin{align*}
        g_{xx} &= \frac{\partial}{\partial x} \left[ -y(x^2 + y^2)^{-1} \right] \\
        &= -y \cdot (-1)(x^2 + y^2)^{-2} \cdot \frac{\partial}{\partial x}(x^2 + y^2) \\
        &= y(x^2 + y^2)^{-2} \cdot (2x) \\
        &= \frac{2xy}{(x^2 + y^2)^2}.
    \end{align*}

    For $g_{yy}$, differentiate $g_y = x(x^2+y^2)^{-1}$ with respect to $y$. Using the chain rule:
    \begin{align*}
        g_{yy} &= \frac{\partial}{\partial y} \left[ x(x^2 + y^2)^{-1} \right] \\
        &= x \cdot (-1)(x^2 + y^2)^{-2} \cdot \frac{\partial}{\partial y}(x^2 + y^2) \\
        &= -x(x^2 + y^2)^{-2} \cdot (2y) \\
        &= \frac{-2xy}{(x^2 + y^2)^2}.
    \end{align*}

    For $g_{xy}$, differentiate $g_x = \frac{-y}{x^2 + y^2}$ with respect to $y$. We use the quotient rule where $u = -y$ and $v = x^2 + y^2$:
    \begin{align*}
        g_{xy} &= \frac{\partial}{\partial y} \left(\frac{-y}{x^2 + y^2} \right) \\
        &= \frac{(-1)(x^2 + y^2) - (-y)(2y)}{(x^2 + y^2)^2} \\
        &= \frac{-x^2 - y^2 + 2y^2}{(x^2 + y^2)^2} \\
        &= \frac{y^2 - x^2}{(x^2 + y^2)^2}.
    \end{align*}

    For $g_{yx}$, differentiate $g_y = \frac{x}{x^2 + y^2}$ with respect to $x$. We use the quotient rule where $u = x$ and $v = x^2 + y^2$:
    \begin{align*}
        g_{yx} &= \frac{\partial}{\partial x} \left(\frac{x}{x^2 + y^2} \right) \\
        &= \frac{(1)(x^2 + y^2) - (x)(2x)}{(x^2 + y^2)^2} \\
        &= \frac{x^2 + y^2 - 2x^2}{(x^2 + y^2)^2} \\
        &= \frac{y^2 - x^2}{(x^2 + y^2)^2}.
    \end{align*}

    \textit{Note: Again, we verify that $g_{xy} = g_{yx}$.}
\end{enumerate}

