latexcode:
Express $\dfrac{\partial w}{\partial u}$ and $\dfrac{\partial w}{\partial v}$ in terms of $u$ and $v$:
    \begin{itemize}
        \item{$w = 4e^x \ln y$, where $x = \ln(u \cos v)$, $y = u \sin v$}
        \item{$w = xy + yz + zx$, where $x = u + v$, $y = u - v$, $z = uv$}
    \end{itemize}

Solution:
To find the partial derivatives $\frac{\partial w}{\partial u}$ and $\frac{\partial w}{\partial v}$, we will apply the Multivariable Chain Rule.

\begin{enumerate}
    \item \textbf{Case 1:} $w = 4e^x \ln y$, where $x = \ln(u \cos v)$ and $y = u \sin v$.

    By the Chain Rule, the partial derivatives are given by:
    \begin{align}
        \frac{\partial w}{\partial u} &= \frac{\partial w}{\partial x}\frac{\partial x}{\partial u} + \frac{\partial w}{\partial y}\frac{\partial y}{\partial u} \label{eq:chain1_u} \\
        \frac{\partial w}{\partial v} &= \frac{\partial w}{\partial x}\frac{\partial x}{\partial v} + \frac{\partial w}{\partial y}\frac{\partial y}{\partial v} \label{eq:chain1_v}
    \end{align}

    \textbf{Step 1: Compute partial derivatives with respect to intermediate variables $x$ and $y$.}
    \begin{align*}
        \frac{\partial w}{\partial x} &= \frac{\partial}{\partial x}(4e^x \ln y) = 4e^x \ln y \\
        \frac{\partial w}{\partial y} &= \frac{\partial}{\partial y}(4e^x \ln y) = \frac{4e^x}{y}
    \end{align*}

    \textbf{Step 2: Compute partial derivatives of $x$ and $y$ with respect to $u$ and $v$.}
    Given $x = \ln(u \cos v) = \ln u + \ln(\cos v)$ and $y = u \sin v$:
    \begin{align*}
        \frac{\partial x}{\partial u} &= \frac{1}{u} & \frac{\partial y}{\partial u} &= \sin v \\
        \frac{\partial x}{\partial v} &= \frac{1}{\cos v}(-\sin v) = -\tan v & \frac{\partial y}{\partial v} &= u \cos v
    \end{align*}

    \textbf{Step 3: Substitute these results into the Chain Rule formulas.}
    Before substituting into the final expression, it is helpful to express the terms involving $x$ and $y$ explicitly in terms of $u$ and $v$:
    \begin{align*}
        e^x &= e^{\ln(u \cos v)} = u \cos v \\
        \ln y &= \ln(u \sin v)
    \end{align*}

    Now, for $\frac{\partial w}{\partial u}$:
    \begin{align*}
        \frac{\partial w}{\partial u} &= (4e^x \ln y) \left(\frac{1}{u} \right) + \left(\frac{4e^x}{y} \right) (\sin v) \\
        &= \left(4(u \cos v) \ln(u \sin v) \right) \frac{1}{u} + \left(\frac{4(u \cos v)}{u \sin v} \right) \sin v \\
        &= 4 \cos v \ln(u \sin v) + 4 \cos v \\
        &= 4 \cos v \left(\ln(u \sin v) + 1 \right)
    \end{align*}

    And for $\frac{\partial w}{\partial v}$:
    \begin{align*}
        \frac{\partial w}{\partial v} &= (4e^x \ln y) (-\tan v) + \left(\frac{4e^x}{y} \right) (u \cos v) \\
        &= \left(4 u \cos v \ln(u \sin v) \right) \left(-\frac{\sin v}{\cos v} \right) + \left(\frac{4 u \cos v}{u \sin v} \right) (u \cos v) \\
        &= -4 u \sin v \ln(u \sin v) + \frac{4 u^2 \cos^2 v}{u \sin v} \\
        &= -4 u \sin v \ln(u \sin v) + \frac{4 u \cos^2 v}{\sin v}
    \end{align*}

    \textbf{Final Answer for Case 1:}
    \begin{align*}
        \frac{\partial w}{\partial u} &= 4 \cos v \left(\ln(u \sin v) + 1 \right) \\
        \frac{\partial w}{\partial v} &= 4u \left(\frac{\cos^2 v}{\sin v} - \sin v \ln(u \sin v) \right)
    \end{align*}

    \vspace{1em}

    \item \textbf{Case 2:} $w = xy + yz + zx$, where $x = u + v$, $y = u - v$, and $z = uv$.

    Since $w$ is a function of three intermediate variables $x, y, z$, the Chain Rule is:
    \begin{align}
        \frac{\partial w}{\partial u} &= \frac{\partial w}{\partial x}\frac{\partial x}{\partial u} + \frac{\partial w}{\partial y}\frac{\partial y}{\partial u} + \frac{\partial w}{\partial z}\frac{\partial z}{\partial u} \\
        \frac{\partial w}{\partial v} &= \frac{\partial w}{\partial x}\frac{\partial x}{\partial v} + \frac{\partial w}{\partial y}\frac{\partial y}{\partial v} + \frac{\partial w}{\partial z}\frac{\partial z}{\partial v}
    \end{align}

    \textbf{Step 1: Compute partial derivatives of $w$ with respect to $x, y, z$.}
    \begin{align*}
        \frac{\partial w}{\partial x} &= y + z \\
        \frac{\partial w}{\partial y} &= x + z \\
        \frac{\partial w}{\partial z} &= y + x
    \end{align*}

    \textbf{Step 2: Compute partial derivatives of $x, y, z$ with respect to $u, v$.}
    \begin{align*}
        \frac{\partial x}{\partial u} &= 1 & \frac{\partial x}{\partial v} &= 1 \\
        \frac{\partial y}{\partial u} &= 1 & \frac{\partial y}{\partial v} &= -1 \\
        \frac{\partial z}{\partial u} &= v & \frac{\partial z}{\partial v} &= u
    \end{align*}

    \textbf{Step 3: Substitute and simplify.}
    First, express the partials of $w$ in terms of $u$ and $v$:
    \begin{align*}
        \frac{\partial w}{\partial x} &= (u - v) + uv \\
        \frac{\partial w}{\partial y} &= (u + v) + uv \\
        \frac{\partial w}{\partial z} &= (u - v) + (u + v) = 2u
    \end{align*}

    Now, calculate $\frac{\partial w}{\partial u}$:
    \begin{align*}
        \frac{\partial w}{\partial u} &= (u - v + uv)(1) + (u + v + uv)(1) + (2u)(v) \\
        &= u - v + uv + u + v + uv + 2uv \\
        &= 2u + 4uv
    \end{align*}

    Calculate $\frac{\partial w}{\partial v}$:
    \begin{align*}
        \frac{\partial w}{\partial v} &= (u - v + uv)(1) + (u + v + uv)(-1) + (2u)(u) \\
        &= (u - v + uv) - (u + v + uv) + 2u^2 \\
        &= u - v + uv - u - v - uv + 2u^2 \\
        &= -2v + 2u^2
    \end{align*}

    \textbf{Final Answer for Case 2:}
    \begin{align*}
        \frac{\partial w}{\partial u} &= 2u(1 + 2v) \\
        \frac{\partial w}{\partial v} &= 2(u^2 - v)
    \end{align*}
\end{enumerate}

