latexcode:
Find the directional derivative of $f$ at $P_0$ in the direction of $\vec{A}$:
    \begin{itemize}
        \item{$f(x, y) = \tan^{-1}(y/x) + \sqrt{3} \sin^{-1}(xy/2)$, $P_0 = (1, 1)$, $\vec{A} = 3\hat{i} - 2\hat{j}$}
        \item{$f(x, y, z) = x^2 + 2y^2 - 3z^2$, $P_0 = (1, 1, 1)$, $\vec{A} = \hat{i} + \hat{j} + \hat{k}$}
    \end{itemize}

Solution:
To find the directional derivative of a scalar field $f$ at a point $P_0$ in the direction of a vector $\vec{A}$, we use the formula:
\[
D_{\vec{u}}f(P_0) = \nabla f(P_0) \cdot \vec{u}
\]
where $\nabla f(P_0)$ is the gradient of $f$ evaluated at $P_0$, and $\vec{u} = \frac{\vec{A}}{\|\vec{A}\|}$ is the unit vector in the direction of $\vec{A}$.

\begin{enumerate}[label=\textbf{\arabic*.}]
    \item \textbf{Problem 1}

    Given:
    \[
    f(x, y) = \tan^{-1}\left(\frac{y}{x}\right) + \sqrt{3} \sin^{-1}\left(\frac{xy}{2}\right), \quad P_0 = (1, 1), \quad \vec{A} = 3\hat{i} - 2\hat{j}
    \]

    \textbf{Step 1: Calculate the gradient $\nabla f(x, y)$.}

    The gradient is defined as $\nabla f = \left\langle \frac{\partial f}{\partial x}, \frac{\partial f}{\partial y} \right\rangle$. We compute the partial derivatives using the chain rule.

    For the partial derivative with respect to $x$:
    \begin{align*}
    \frac{\partial f}{\partial x} &= \frac{\partial}{\partial x}\left[ \tan^{-1}\left(\frac{y}{x}\right) \right] + \frac{\partial}{\partial x}\left[ \sqrt{3} \sin^{-1}\left(\frac{xy}{2}\right) \right] \\
    &= \frac{1}{1 + (y/x)^2} \cdot \left(-\frac{y}{x^2}\right) + \sqrt{3} \cdot \frac{1}{\sqrt{1 - (xy/2)^2}} \cdot \left(\frac{y}{2}\right) \\
    &= \frac{x^2}{x^2 + y^2} \cdot \left(-\frac{y}{x^2}\right) + \frac{\sqrt{3}y}{2\sqrt{1 - \frac{x^2y^2}{4}}} \\
    &= -\frac{y}{x^2 + y^2} + \frac{\sqrt{3}y}{\sqrt{4 - x^2y^2}}.
    \end{align*}

    For the partial derivative with respect to $y$:
    \begin{align*}
    \frac{\partial f}{\partial y} &= \frac{\partial}{\partial y}\left[ \tan^{-1}\left(\frac{y}{x}\right) \right] + \frac{\partial}{\partial y}\left[ \sqrt{3} \sin^{-1}\left(\frac{xy}{2}\right) \right] \\
    &= \frac{1}{1 + (y/x)^2} \cdot \left(\frac{1}{x}\right) + \sqrt{3} \cdot \frac{1}{\sqrt{1 - (xy/2)^2}} \cdot \left(\frac{x}{2}\right) \\
    &= \frac{x^2}{x^2 + y^2} \cdot \left(\frac{1}{x}\right) + \frac{\sqrt{3}x}{2\sqrt{1 - \frac{x^2y^2}{4}}} \\
    &= \frac{x}{x^2 + y^2} + \frac{\sqrt{3}x}{\sqrt{4 - x^2y^2}}.
    \end{align*}

    \textbf{Step 2: Evaluate the gradient at $P_0 = (1, 1)$.}

    Substitute $x=1$ and $y=1$ into the partial derivatives:
    \begin{align*}
    f_x(1, 1) &= -\frac{1}{1^2 + 1^2} + \frac{\sqrt{3}(1)}{\sqrt{4 - (1)^2(1)^2}} = -\frac{1}{2} + \frac{\sqrt{3}}{\sqrt{3}} = -\frac{1}{2} + 1 = \frac{1}{2}. \\
    f_y(1, 1) &= \frac{1}{1^2 + 1^2} + \frac{\sqrt{3}(1)}{\sqrt{4 - (1)^2(1)^2}} = \frac{1}{2} + \frac{\sqrt{3}}{\sqrt{3}} = \frac{1}{2} + 1 = \frac{3}{2}.
    \end{align*}
    Thus, $\nabla f(1, 1) = \left\langle \frac{1}{2}, \frac{3}{2} \right\rangle$.

    \textbf{Step 3: Determine the unit direction vector $\vec{u}$.}

    The given vector is $\vec{A} = \langle 3, -2 \rangle$. Its magnitude is:
    \[
    \|\vec{A}\| = \sqrt{3^2 + (-2)^2} = \sqrt{9 + 4} = \sqrt{13}.
    \]
    The unit vector is:
    \[
    \vec{u} = \frac{\vec{A}}{\|\vec{A}\|} = \left\langle \frac{3}{\sqrt{13}}, -\frac{2}{\sqrt{13}} \right\rangle.
    \]

    \textbf{Step 4: Calculate the directional derivative.}

    \begin{align*}
    D_{\vec{u}}f(1, 1) &= \nabla f(1, 1) \cdot \vec{u} \\
    &= \left\langle \frac{1}{2}, \frac{3}{2} \right\rangle \cdot \left\langle \frac{3}{\sqrt{13}}, -\frac{2}{\sqrt{13}} \right\rangle \\
    &= \left(\frac{1}{2} \cdot \frac{3}{\sqrt{13}} \right) + \left(\frac{3}{2} \cdot -\frac{2}{\sqrt{13}} \right) \\
    &= \frac{3}{2\sqrt{13}} - \frac{6}{2\sqrt{13}} \\
    &= -\frac{3}{2\sqrt{13}}.
    \end{align*}

    \textbf{Answer:} $-\frac{3}{2\sqrt{13}}$ (or $-\frac{3\sqrt{13}}{26}$).

    \vspace{1em}
    \hrule
    \vspace{1em}

    \item \textbf{Problem 2}

    Given:
    \[
    f(x, y, z) = x^2 + 2y^2 - 3z^2, \quad P_0 = (1, 1, 1), \quad \vec{A} = \hat{i} + \hat{j} + \hat{k}
    \]

    \textbf{Step 1: Calculate the gradient $\nabla f(x, y, z)$.}

    Compute the partial derivatives:
    \begin{align*}
    \frac{\partial f}{\partial x} &= 2x, \\
    \frac{\partial f}{\partial y} &= 4y, \\
    \frac{\partial f}{\partial z} &= -6z.
    \end{align*}
    Thus, $\nabla f(x, y, z) = \langle 2x, 4y, -6z \rangle$.

    \textbf{Step 2: Evaluate the gradient at $P_0 = (1, 1, 1)$.}

    \[
    \nabla f(1, 1, 1) = \langle 2(1), 4(1), -6(1) \rangle = \langle 2, 4, -6 \rangle.
    \]

    \textbf{Step 3: Determine the unit direction vector $\vec{u}$.}

    The given vector is $\vec{A} = \langle 1, 1, 1 \rangle$. Its magnitude is:
    \[
    \|\vec{A}\| = \sqrt{1^2 + 1^2 + 1^2} = \sqrt{3}.
    \]
    The unit vector is:
    \[
    \vec{u} = \frac{\vec{A}}{\|\vec{A}\|} = \left\langle \frac{1}{\sqrt{3}}, \frac{1}{\sqrt{3}}, \frac{1}{\sqrt{3}} \right\rangle.
    \]

    \textbf{Step 4: Calculate the directional derivative.}

    \begin{align*}
    D_{\vec{u}}f(1, 1, 1) &= \nabla f(1, 1, 1) \cdot \vec{u} \\
    &= \langle 2, 4, -6 \rangle \cdot \left\langle \frac{1}{\sqrt{3}}, \frac{1}{\sqrt{3}}, \frac{1}{\sqrt{3}} \right\rangle \\
    &= \frac{2}{\sqrt{3}} + \frac{4}{\sqrt{3}} - \frac{6}{\sqrt{3}} \\
    &= \frac{2 + 4 - 6}{\sqrt{3}} \\
    &= 0.
    \end{align*}

    \textbf{Answer:} $0$.
\end{enumerate}

\hfill [Generated by gemini-3-pro]

latexcode:
Find the directions in which the functions increase and decrease most rapidly at $P_0$. Then find the derivative of the function in these directions:
    \begin{itemize}
        \item{$f(x, y) = x^2 + xy + y^2$, $P_0 = (1, 1)$}
        \item{$f(x, y, z) = x e^y + z^2$, $P_0 = (1, \ln 2, 1/2)$}
    \end{itemize}

Find the equation of the tangent plane and the normal line at $P_0$ on the given surface:
    \begin{itemize}
        \item{$x^2 + y^2 - z^2 = 18$, $P_0 = (3, 5, -4)$}
        \item{$x^2 - xy - y^2 - z = 0$, $P_0 = (1, 1, -1)$}
    \end{itemize}

Solution:
To find the equation of the tangent plane and the normal line to a surface at a specific point, we utilize the gradient vector.

\textbf{General Theory:}
Let a surface be defined by the level set $F(x, y, z) = c$. The gradient vector $\nabla F$ at a point $P_0(x_0, y_0, z_0)$ is normal (orthogonal) to the tangent plane at that point.
\[ \nabla F(P_0) = \langle F_x(P_0), F_y(P_0), F_z(P_0) \rangle = \mathbf{n} \]
The equation of the \textbf{tangent plane} is:
\[ F_x(P_0)(x - x_0) + F_y(P_0)(y - y_0) + F_z(P_0)(z - z_0) = 0 \]
The parametric equations for the \textbf{normal line} are:
\[ x = x_0 + F_x(P_0)t, \quad y = y_0 + F_y(P_0)t, \quad z = z_0 + F_z(P_0)t \]

\begin{enumerate}
    \item \textbf{Surface:} $x^2 + y^2 - z^2 = 18$, \textbf{Point:} $P_0 = (3, 5, -4)$.

    \textbf{Step 1: Define the function and find the gradient.}
    Let $F(x, y, z) = x^2 + y^2 - z^2$. The surface is the level set $F(x, y, z) = 18$.
    We compute the partial derivatives:
    \begin{align*}
        F_x(x, y, z) &= \frac{\partial}{\partial x}(x^2 + y^2 - z^2) = 2x \\
        F_y(x, y, z) &= \frac{\partial}{\partial y}(x^2 + y^2 - z^2) = 2y \\
        F_z(x, y, z) &= \frac{\partial}{\partial z}(x^2 + y^2 - z^2) = -2z
    \end{align*}

    \textbf{Step 2: Evaluate the gradient at $P_0$.}
    Substitute $x=3, y=5, z=-4$ into the partial derivatives:
    \begin{align*}
        F_x(3, 5, -4) &= 2(3) = 6 \\
        F_y(3, 5, -4) &= 2(5) = 10 \\
        F_z(3, 5, -4) &= -2(-4) = 8
    \end{align*}
    The normal vector is $\mathbf{n} = \langle 6, 10, 8 \rangle$. For the sake of simplification in the plane equation, we can use the parallel vector $\frac{1}{2}\mathbf{n} = \langle 3, 5, 4 \rangle$.

    \textbf{Step 3: Find the Tangent Plane.}
    Using the simplified normal vector $\langle 3, 5, 4 \rangle$:
    \begin{align*}
        3(x - 3) + 5(y - 5) + 4(z - (-4)) &= 0 \\
        3(x - 3) + 5(y - 5) + 4(z + 4) &= 0 \\
        3x - 9 + 5y - 25 + 4z + 16 &= 0 \\
        3x + 5y + 4z - 18 &= 0
    \end{align*}
    \textbf{Tangent Plane Equation:} $\boxed{3x + 5y + 4z = 18}$

    \textbf{Step 4: Find the Normal Line.}
    Using the point $(3, 5, -4)$ and the direction vector $\langle 3, 5, 4 \rangle$:
    \textbf{Normal Line Equations:} $\boxed{x = 3 + 3t, \quad y = 5 + 5t, \quad z = -4 + 4t}$

    \vspace{1em}

    \item \textbf{Surface:} $x^2 - xy - y^2 - z = 0$, \textbf{Point:} $P_0 = (1, 1, -1)$.

    \textbf{Step 1: Define the function and find the gradient.}
    Let $G(x, y, z) = x^2 - xy - y^2 - z$. The surface is the level set $G(x, y, z) = 0$.
    We compute the partial derivatives:
    \begin{align*}
        G_x(x, y, z) &= 2x - y \\
        G_y(x, y, z) &= -x - 2y \\
        G_z(x, y, z) &= -1
    \end{align*}

    \textbf{Step 2: Evaluate the gradient at $P_0$.}
    Substitute $x=1, y=1, z=-1$:
    \begin{align*}
        G_x(1, 1, -1) &= 2(1) - 1 = 1 \\
        G_y(1, 1, -1) &= -(1) - 2(1) = -3 \\
        G_z(1, 1, -1) &= -1
    \end{align*}
    The normal vector is $\mathbf{n} = \langle 1, -3, -1 \rangle$.

    \textbf{Step 3: Find the Tangent Plane.}
    Using the normal vector $\langle 1, -3, -1 \rangle$:
    \begin{align*}
        1(x - 1) - 3(y - 1) - 1(z - (-1)) &= 0 \\
        (x - 1) - 3(y - 1) - (z + 1) &= 0 \\
        x - 1 - 3y + 3 - z - 1 &= 0 \\
        x - 3y - z + 1 &= 0
    \end{align*}
    \textbf{Tangent Plane Equation:} $\boxed{x - 3y - z = -1}$

    \textbf{Step 4: Find the Normal Line.}
    Using the point $(1, 1, -1)$ and the direction vector $\langle 1, -3, -1 \rangle$:
    \textbf{Normal Line Equations:} $\boxed{x = 1 + t, \quad y = 1 - 3t, \quad z = -1 - t}$
\end{enumerate}

\hfill [Generated by gemini-3-pro]

latexcode:
Find all the local maxima, local minima, and saddle points of the following functions:
    \begin{itemize}
        \item{$f(x, y) = x^3 + y^3 + 3x^2 - 3y^2 - 8$}
        \item{$f(x, y) = 2x^3 + 2y^3 - 9x^2 + 3y^2 - 12y$}
        \item{$f(x, y) = y \sin x$}
        \item{$f(x, y) = e^{2x} \cos y$}
    \end{itemize}

Solution:
To find the local maxima, local minima, and saddle points of a function $f(x,y)$, we utilize the Second Derivative Test. The general procedure is as follows:

\begin{enumerate}
    \item Find the first partial derivatives $f_x$ and $f_y$.
    \item Determine the critical points by solving the system of equations $f_x(x,y) = 0$ and $f_y(x,y) = 0$.
    \item Compute the second partial derivatives $f_{xx}$, $f_{yy}$, and $f_{xy}$.
    \item Evaluate the discriminant (Hessian determinant) $D = f_{xx}f_{yy} - (f_{xy})^2$ at each critical point $(a,b)$.
    \item Classify the points:
    \begin{itemize}
        \item If $D(a,b) > 0$ and $f_{xx}(a,b) > 0$, then $f(a,b)$ is a local minimum.
        \item If $D(a,b) > 0$ and $f_{xx}(a,b) < 0$, then $f(a,b)$ is a local maximum.
        \item If $D(a,b) < 0$, then $(a,b)$ is a saddle point.
        \item If $D(a,b) = 0$, the test is inconclusive.
    \end{itemize}
\end{enumerate}

\noindent We now apply this method to each function.

\begin{enumerate}
    % PROBLEM 1
    \item \textbf{Function:} $f(x, y) = x^3 + y^3 + 3x^2 - 3y^2 - 8$

    \textbf{Step 1: First Partial Derivatives}
    \begin{align*}
        f_x &= 3x^2 + 6x = 3x(x+2) \\
        f_y &= 3y^2 - 6y = 3y(y-2)
    \end{align*}

    \textbf{Step 2: Critical Points}
    Setting $f_x = 0$ yields $x = 0$ or $x = -2$. Setting $f_y = 0$ yields $y = 0$ or $y = 2$. Since the variables are independent, we consider all combinations of these values. The critical points are:
    \[ (0,0), \quad (0,2), \quad (-2,0), \quad (-2,2) \]

    \textbf{Step 3: Second Partial Derivatives and Discriminant}
    \begin{align*}
        f_{xx} &= 6x + 6 \\
        f_{yy} &= 6y - 6 \\
        f_{xy} &= 0
    \end{align*}
    The discriminant is $D(x,y) = (6x+6)(6y-6) - 0^2 = 36(x+1)(y-1)$.

    \textbf{Step 4: Classification}
    \begin{itemize}
        \item \textbf{At $(0,0)$:}
        \[ D(0,0) = 36(1)(-1) = -36 < 0 \]
        Conclusion: \textbf{Saddle Point}.

        \item \textbf{At $(0,2)$:}
        \[ D(0,2) = 36(1)(1) = 36 > 0 \]
        Check $f_{xx}(0,2) = 6(0)+6 = 6 > 0$.
        Conclusion: \textbf{Local Minimum}.

        \item \textbf{At $(-2,0)$:}
        \[ D(-2,0) = 36(-1)(-1) = 36 > 0 \]
        Check $f_{xx}(-2,0) = 6(-2)+6 = -6 < 0$.
        Conclusion: \textbf{Local Maximum}.

        \item \textbf{At $(-2,2)$:}
        \[ D(-2,2) = 36(-1)(1) = -36 < 0 \]
        Conclusion: \textbf{Saddle Point}.
    \end{itemize}

    \vspace{0.5cm}

    % PROBLEM 2
    \item \textbf{Function:} $f(x, y) = 2x^3 + 2y^3 - 9x^2 + 3y^2 - 12y$

    \textbf{Step 1: First Partial Derivatives}
    \begin{align*}
        f_x &= 6x^2 - 18x = 6x(x-3) \\
        f_y &= 6y^2 + 6y - 12 = 6(y^2 + y - 2) = 6(y+2)(y-1)
    \end{align*}

    \textbf{Step 2: Critical Points}
    From $f_x = 0$, we have $x = 0$ or $x = 3$. From $f_y = 0$, we have $y = -2$ or $y = 1$. The critical points are:
    \[ (0, -2), \quad (0, 1), \quad (3, -2), \quad (3, 1) \]

    \textbf{Step 3: Second Partial Derivatives and Discriminant}
    \begin{align*}
        f_{xx} &= 12x - 18 = 6(2x-3) \\
        f_{yy} &= 12y + 6 = 6(2y+1) \\
        f_{xy} &= 0
    \end{align*}
    The discriminant is $D(x,y) = 36(2x-3)(2y+1)$.

    \textbf{Step 4: Classification}
    \begin{itemize}
        \item \textbf{At $(0, -2)$:}
        \[ D(0, -2) = 36(-3)(-3) = 324 > 0 \]
        Check $f_{xx}(0, -2) = -18 < 0$.
        Conclusion: \textbf{Local Maximum}.

        \item \textbf{At $(0, 1)$:}
        \[ D(0, 1) = 36(-3)(3) = -324 < 0 \]
        Conclusion: \textbf{Saddle Point}.

        \item \textbf{At $(3, -2)$:}
        \[ D(3, -2) = 36(3)(-3) = -324 < 0 \]
        Conclusion: \textbf{Saddle Point}.

        \item \textbf{At $(3, 1)$:}
        \[ D(3, 1) = 36(3)(3) = 324 > 0 \]
        Check $f_{xx}(3, 1) = 18 > 0$.
        Conclusion: \textbf{Local Minimum}.
    \end{itemize}

    \vspace{0.5cm}

    % PROBLEM 3
    \item \textbf{Function:} $f(x, y) = y \sin x$

    \textbf{Step 1: First Partial Derivatives}
    \begin{align*}
        f_x &= y \cos x \\
        f_y &= \sin x
    \end{align*}

    \textbf{Step 2: Critical Points}
    We solve the system:
    \begin{enumerate}[label=(\roman*)]
        \item $y \cos x = 0$
        \item $\sin x = 0$
    \end{enumerate}
    From (ii), $\sin x = 0$ implies $x = n\pi$ for any integer $n \in \mathbb{Z}$.
    Substituting $x = n\pi$ into (i), we get $y \cos(n\pi) = 0$. Since $\cos(n\pi) = (-1)^n \neq 0$, we must have $y = 0$.
    Thus, there are infinitely many critical points of the form:
    \[ (n\pi, 0) \quad \text{for } n \in \mathbb{Z} \]

    \textbf{Step 3: Second Partial Derivatives and Discriminant}
    \begin{align*}
        f_{xx} &= -y \sin x \\
        f_{yy} &= 0 \\
        f_{xy} &= \cos x
    \end{align*}
    The discriminant is:
    \[ D(x,y) = f_{xx}f_{yy} - (f_{xy})^2 = (-y \sin x)(0) - (\cos x)^2 = -\cos^2 x \]

    \textbf{Step 4: Classification}
    At any critical point $(n\pi, 0)$:
    \[ D(n\pi, 0) = -\cos^2(n\pi) = -((-1)^n)^2 = -1 \]
    Since $D < 0$ for all $n$, every critical point is a saddle point.

    Conclusion: \textbf{Saddle Points at $(n\pi, 0)$ for all $n \in \mathbb{Z}$}.

    \vspace{0.5cm}

    % PROBLEM 4
    \item \textbf{Function:} $f(x, y) = e^{2x} \cos y$

    \textbf{Step 1: First Partial Derivatives}
    \begin{align*}
        f_x &= 2e^{2x} \cos y \\
        f_y &= -e^{2x} \sin y
    \end{align*}

    \textbf{Step 2: Critical Points}
    We set the derivatives to zero:
    \begin{enumerate}[label=(\roman*)]
        \item $2e^{2x} \cos y = 0$
        \item $-e^{2x} \sin y = 0$
    \end{enumerate}
    Since the exponential function $e^{2x}$ is strictly positive for all real $x$, we can divide both equations by $e^{2x}$ (and constants). The system reduces to:
    \begin{align*}
        \cos y &= 0 \\
        \sin y &= 0
    \end{align*}
    However, there is no real number $y$ that satisfies both $\cos y = 0$ and $\sin y = 0$ simultaneously, because of the Pythagorean identity $\sin^2 y + \cos^2 y = 1$.

    \textbf{Conclusion:} The function has no critical points. Consequently, there are \textbf{no local maxima, local minima, or saddle points}.
\end{enumerate}

