latexcode:
Let $\mathbf{A} \subset \mathbb{R}$ be a nonempty set. Define $-\mathbf{A} = \{x:-x\in \mathbf{A}\}$. Show that:
\begin{align*}
\text{sup}\left(-\mathbf{A}\right) &= -\text{inf}\left(\mathbf{A}\right)\\
\text{inf}\left(-\mathbf{A}\right) &= -\text{sup}\left(\mathbf{A}\right)
\end{align*}

Let $\mathbf{A}, \mathbf{B} \subset \mathbb{R}$ be nonempty. Define
\begin{align*}
\mathbf{A} + \mathbf{B} &= \{z = x + y : x \in \mathbf{A},\ y \in \mathbf{B}\}\\
\mathbf{A} - \mathbf{B} &= \{z = x - y : x \in \mathbf{A},\ y \in \mathbf{B}\}
\end{align*}
Show that
\begin{align*}
\sup(\mathbf{A} + \mathbf{B}) =& \sup \mathbf{A} + \sup \mathbf{B}\\
\sup(\mathbf{A} - \mathbf{B}) =& \sup \mathbf{A} - \inf \mathbf{B}
\end{align*}
Establish analogous formulas for $\inf(\mathbf{A} + \mathbf{B})$ and $\inf(\mathbf{A} - \mathbf{B})$.

Solution:
We assume that the sets $\mathbf{A}$ and $\mathbf{B}$ are bounded. If the sets are unbounded, the results hold in the extended real number system $\overline{\mathbb{R}}$ (where, for example, $\sup \mathbf{A} = \infty$ if $\mathbf{A}$ is not bounded above), but the proofs below focus on the standard case where suprema and infima are real numbers.

\begin{proof}
\textbf{Part 1: The Supremum of the Sum}

We aim to show that $\sup(\mathbf{A} + \mathbf{B}) = \sup \mathbf{A} + \sup \mathbf{B}$. Let $\alpha = \sup \mathbf{A}$ and $\beta = \sup \mathbf{B}$.

\begin{enumerate}[label=(\roman*)]
    \item \textit{Upper Bound Condition:}
    By the definition of supremum, for any $x \in \mathbf{A}$, $x \leq \alpha$. Similarly, for any $y \in \mathbf{B}$, $y \leq \beta$. Adding these inequalities, we obtain:
    \[
    x + y \leq \alpha + \beta \quad \text{for all } x \in \mathbf{A}, y \in \mathbf{B}.
    \]
    Since every element $z \in \mathbf{A} + \mathbf{B}$ is of the form $x+y$, it follows that $\alpha + \beta$ is an upper bound for the set $\mathbf{A} + \mathbf{B}$. Consequently,
    \begin{equation} \label{eq:supsum1}
    \sup(\mathbf{A} + \mathbf{B}) \leq \alpha + \beta.
    \end{equation}

    \item \textit{Least Upper Bound Condition:}
    Let $\varepsilon > 0$ be arbitrary. We must show there exists an element $z \in \mathbf{A} + \mathbf{B}$ such that $z > (\alpha + \beta) - \varepsilon$.

    Since $\alpha = \sup \mathbf{A}$, there exists some $x_0 \in \mathbf{A}$ such that:
    \[
    x_0 > \alpha - \frac{\varepsilon}{2}.
    \]
    Since $\beta = \sup \mathbf{B}$, there exists some $y_0 \in \mathbf{B}$ such that:
    \[
    y_0 > \beta - \frac{\varepsilon}{2}.
    \]
    Let $z_0 = x_0 + y_0$. Then $z_0 \in \mathbf{A} + \mathbf{B}$, and summing the inequalities yields:
    \[
    z_0 = x_0 + y_0 > \left(\alpha - \frac{\varepsilon}{2}\right) + \left(\beta - \frac{\varepsilon}{2}\right) = \alpha + \beta - \varepsilon.
    \]
    Since $\varepsilon$ was arbitrary, $\alpha + \beta$ is the \textit{least} upper bound. Thus,
    \begin{equation} \label{eq:supsum2}
    \sup(\mathbf{A} + \mathbf{B}) \geq \alpha + \beta.
    \end{equation}
\end{enumerate}
Combining \eqref{eq:supsum1} and \eqref{eq:supsum2}, we conclude $\sup(\mathbf{A} + \mathbf{B}) = \sup \mathbf{A} + \sup \mathbf{B}$.

\vspace{1em}

\textbf{Part 2: The Supremum of the Difference}

We aim to show that $\sup(\mathbf{A} - \mathbf{B}) = \sup \mathbf{A} - \inf \mathbf{B}$. Let $\alpha = \sup \mathbf{A}$ and $\gamma = \inf \mathbf{B}$.

\begin{enumerate}[label=(\roman*)]
    \item \textit{Upper Bound Condition:}
    For any $x \in \mathbf{A}$, $x \leq \alpha$. For any $y \in \mathbf{B}$, $y \geq \gamma$ (by definition of infimum). Multiplying the second inequality by $-1$ reverses it: $-y \leq -\gamma$.

    Adding the inequalities for $x$ and $-y$:
    \[
    x - y \leq \alpha - \gamma \quad \text{for all } x \in \mathbf{A}, y \in \mathbf{B}.
    \]
    Thus, $\alpha - \gamma$ is an upper bound for $\mathbf{A} - \mathbf{B}$, implying:
    \begin{equation} \label{eq:supdiff1}
    \sup(\mathbf{A} - \mathbf{B}) \leq \sup \mathbf{A} - \inf \mathbf{B}.
    \end{equation}

    \item \textit{Least Upper Bound Condition:}
    Let $\varepsilon > 0$.
    Since $\alpha = \sup \mathbf{A}$, there exists $x_0 \in \mathbf{A}$ such that $x_0 > \alpha - \frac{\varepsilon}{2}$.
    Since $\gamma = \inf \mathbf{B}$, there exists $y_0 \in \mathbf{B}$ such that $y_0 < \gamma + \frac{\varepsilon}{2}$.

    Multiplying the inequality for $y_0$ by $-1$ gives $-y_0 > -\gamma - \frac{\varepsilon}{2}$. Adding this to the inequality for $x_0$:
    \[
    x_0 - y_0 > \left(\alpha - \frac{\varepsilon}{2}\right) + \left(-\gamma - \frac{\varepsilon}{2}\right) = \alpha - \gamma - \varepsilon.
    \]
    Thus, there exists an element in $\mathbf{A} - \mathbf{B}$ strictly greater than $(\alpha - \gamma) - \varepsilon$. This implies:
    \begin{equation} \label{eq:supdiff2}
    \sup(\mathbf{A} - \mathbf{B}) \geq \sup \mathbf{A} - \inf \mathbf{B}.
    \end{equation}
\end{enumerate}
Combining \eqref{eq:supdiff1} and \eqref{eq:supdiff2}, we conclude $\sup(\mathbf{A} - \mathbf{B}) = \sup \mathbf{A} - \inf \mathbf{B}$.

\vspace{1em}

\textbf{Part 3: Analogous Formulas for Infimum}

The analogous formulas are:
\begin{align*}
\inf(\mathbf{A} + \mathbf{B}) &= \inf \mathbf{A} + \inf \mathbf{B} \\
\inf(\mathbf{A} - \mathbf{B}) &= \inf \mathbf{A} - \sup \mathbf{B}
\end{align*}

\textit{Proof for $\inf(\mathbf{A} + \mathbf{B})$:}
Let $\delta = \inf \mathbf{A}$ and $\gamma = \inf \mathbf{B}$.
For all $x \in \mathbf{A}, y \in \mathbf{B}$, we have $x \geq \delta$ and $y \geq \gamma$, so $x+y \geq \delta + \gamma$. Thus $\delta + \gamma$ is a lower bound.
For any $\varepsilon > 0$, there exist $x_0 \in \mathbf{A}$ and $y_0 \in \mathbf{B}$ such that $x_0 < \delta + \varepsilon/2$ and $y_0 < \gamma + \varepsilon/2$. Then $x_0+y_0 < \delta + \gamma + \varepsilon$. Thus $\delta + \gamma$ is the greatest lower bound.

\textit{Proof for $\inf(\mathbf{A} - \mathbf{B})$:}
Let $\delta = \inf \mathbf{A}$ and $\beta = \sup \mathbf{B}$.
For all $x \in \mathbf{A}, y \in \mathbf{B}$, we have $x \geq \delta$ and $y \leq \beta$. The latter implies $-y \geq -\beta$. Adding these gives $x - y \geq \delta - \beta$. Thus $\delta - \beta$ is a lower bound.
For any $\varepsilon > 0$, there exist $x_0 \in \mathbf{A}$ such that $x_0 < \delta + \varepsilon/2$ and $y_0 \in \mathbf{B}$ such that $y_0 > \beta - \varepsilon/2$ (which implies $-y_0 < -\beta + \varepsilon/2$). Summing these gives $x_0 - y_0 < \delta - \beta + \varepsilon$. Thus $\delta - \beta$ is the greatest lower bound.
\end{proof}

