Given nonempty subsets $\mathbf{A}$ and $\mathbf{B}$ of positive real numbers, define
\begin{align*}
\mathbf{A} \cdot \mathbf{B} &= \{z = x \cdot y : x \in \mathbf{A},\ y \in \mathbf{B}\}\\
\mathbf{A}^{-1} &= \left\{z = \frac{1}{x} : x \in \mathbf{A} \right\}
\end{align*}
Show that
\begin{align*}
\sup(\mathbf{A} \cdot \mathbf{B}) = \sup \mathbf{A} \cdot \sup \mathbf{B}
\end{align*}
Show also that, if $\inf \mathbf{A} > 0$, then
\begin{align*}
\sup(\mathbf{A}^{-1}) = \frac{1}{\inf \mathbf{A}}
\end{align*}
and, if $\inf \mathbf{A} = 0$, then $\sup(\mathbf{A}^{-1}) = +\infty$. Additionally, show that if $\mathbf{A}$ and $\mathbf{B}$ are bounded sets of real numbers, then
\begin{align*}
\sup(\mathbf{A} \cdot \mathbf{B}) = \max\{\sup \mathbf{A} \cdot \sup \mathbf{B},\ \sup \mathbf{A} \cdot \inf \mathbf{B},\ \inf \mathbf{A} \cdot \sup \mathbf{B},\ \inf \mathbf{A} \cdot \inf \mathbf{B}\}.
\end{align*}

Let $\mathbf{A}$ and $\mathbf{B}$ be nonempty subsets of real numbers. Show that
\begin{align*}
\sup(\mathbf{A} \cup \mathbf{B}) &= \max\{\sup \mathbf{A},\ \sup \mathbf{B}\}\\
\inf(\mathbf{A} \cup \mathbf{B}) &= \min\{\inf \mathbf{A},\ \inf \mathbf{B}\}
\end{align*}

Solution:
\begin{proof}
We assume that the sets $\mathbf{A}$ and $\mathbf{B}$ are bounded. If either set is unbounded, the results hold in the extended real number system (where the supremum or infimum is $\pm \infty$), but the standard rigorous treatment focuses on the bounded case in $\mathbb{R}$.

\textbf{Part 1: Supremum}

Let $\alpha = \sup \mathbf{A}$ and $\beta = \sup \mathbf{B}$. We aim to show that $\sup(\mathbf{A} \cup \mathbf{B}) = \max\{\alpha, \beta\}$. Let $M = \max\{\alpha, \beta\}$.

\begin{enumerate}[label=(\roman*)]
    \item \textbf{Show that $M$ is an upper bound for $\mathbf{A} \cup \mathbf{B}$.}

    Let $x$ be an arbitrary element of $\mathbf{A} \cup \mathbf{B}$. By definition of the union, $x \in \mathbf{A}$ or $x \in \mathbf{B}$.
    \begin{itemize}
        \item If $x \in \mathbf{A}$, then $x \le \sup \mathbf{A} = \alpha$. Since $\alpha \le M$, we have $x \le M$.
        \item If $x \in \mathbf{B}$, then $x \le \sup \mathbf{B} = \beta$. Since $\beta \le M$, we have $x \le M$.
    \end{itemize}
    In either case, $x \le M$ for all $x \in \mathbf{A} \cup \mathbf{B}$. Thus, $M$ is an upper bound for $\mathbf{A} \cup \mathbf{B}$. By the definition of the supremum (the \textit{least} upper bound), we must have:
    \begin{equation} \label{eq:sup1}
        \sup(\mathbf{A} \cup \mathbf{B}) \le M.
    \end{equation}

    \item \textbf{Show that $\sup(\mathbf{A} \cup \mathbf{B}) \ge M$.}

    Recall the property that if $S \subseteq T$, then $\sup S \le \sup T$ (provided the suprema exist).
    \begin{itemize}
        \item Since $\mathbf{A} \subseteq \mathbf{A} \cup \mathbf{B}$, it follows that $\sup \mathbf{A} \le \sup(\mathbf{A} \cup \mathbf{B})$. Thus, $\alpha \le \sup(\mathbf{A} \cup \mathbf{B})$.
        \item Since $\mathbf{B} \subseteq \mathbf{A} \cup \mathbf{B}$, it follows that $\sup \mathbf{B} \le \sup(\mathbf{A} \cup \mathbf{B})$. Thus, $\beta \le \sup(\mathbf{A} \cup \mathbf{B})$.
    \end{itemize}
    Since $\sup(\mathbf{A} \cup \mathbf{B})$ is greater than or equal to both $\alpha$ and $\beta$, it must be greater than or equal to their maximum:
    \begin{equation} \label{eq:sup2}
        \sup(\mathbf{A} \cup \mathbf{B}) \ge \max\{\alpha, \beta\} = M.
    \end{equation}

    \item \textbf{Conclusion.}
    Combining inequalities (\ref{eq:sup1}) and (\ref{eq:sup2}), we obtain:
    \[
    \sup(\mathbf{A} \cup \mathbf{B}) = M = \max\{\sup \mathbf{A}, \sup \mathbf{B}\}.
    \]
\end{enumerate}

\textbf{Part 2: Infimum}

Let $\gamma = \inf \mathbf{A}$ and $\delta = \inf \mathbf{B}$. We aim to show that $\inf(\mathbf{A} \cup \mathbf{B}) = \min\{\gamma, \delta\}$. Let $m = \min\{\gamma, \delta\}$.

\begin{enumerate}[label=(\roman*)]
    \item \textbf{Show that $m$ is a lower bound for $\mathbf{A} \cup \mathbf{B}$.}

    Let $x \in \mathbf{A} \cup \mathbf{B}$.
    \begin{itemize}
        \item If $x \in \mathbf{A}$, then $x \ge \inf \mathbf{A} = \gamma$. Since $\gamma \ge m$, we have $x \ge m$.
        \item If $x \in \mathbf{B}$, then $x \ge \inf \mathbf{B} = \delta$. Since $\delta \ge m$, we have $x \ge m$.
    \end{itemize}
    Thus, $x \ge m$ for all $x \in \mathbf{A} \cup \mathbf{B}$. Since $m$ is a lower bound, and the infimum is the \textit{greatest} lower bound, we have:
    \begin{equation} \label{eq:inf1}
        \inf(\mathbf{A} \cup \mathbf{B}) \ge m.
    \end{equation}

    \item \textbf{Show that $\inf(\mathbf{A} \cup \mathbf{B}) \le m$.}

    Recall the property that if $S \subseteq T$, then $\inf T \le \inf S$.
    \begin{itemize}
        \item Since $\mathbf{A} \subseteq \mathbf{A} \cup \mathbf{B}$, we have $\inf(\mathbf{A} \cup \mathbf{B}) \le \inf \mathbf{A} = \gamma$.
        \item Since $\mathbf{B} \subseteq \mathbf{A} \cup \mathbf{B}$, we have $\inf(\mathbf{A} \cup \mathbf{B}) \le \inf \mathbf{B} = \delta$.
    \end{itemize}
    Since $\inf(\mathbf{A} \cup \mathbf{B})$ is less than or equal to both $\gamma$ and $\delta$, it must be less than or equal to their minimum:
    \begin{equation} \label{eq:inf2}
        \inf(\mathbf{A} \cup \mathbf{B}) \le \min\{\gamma, \delta\} = m.
    \end{equation}

    \item \textbf{Conclusion.}
    Combining inequalities (\ref{eq:inf1}) and (\ref{eq:inf2}), we obtain:
    \[
    \inf(\mathbf{A} \cup \mathbf{B}) = m = \min\{\inf \mathbf{A}, \inf \mathbf{B}\}.
    \]
\end{enumerate}
\end{proof}

