latexcode:
Find the least upper bound and the greatest lower bound of
\begin{align*}
\mathbf{A}_1 &= \left\{ 2(-1)^{n+1}+(-1)^{\frac{n(n+1)}{2}}\left(2+\frac{3}{n}\right) : n \in \mathbb{N} \right\}\\
\mathbf{A}_2 &= \left\{ \frac{n-1}{n+1} \cos\left(\frac{2n\pi}{3} \right) : n \in \mathbb{N} \right\}
\end{align*}

Find the supremum and the infimum of the set of numbers
\begin{align*}
\left\{ \frac{(n+m)^2}{2^{nm}} : n, m \in \mathbb{N} \right\}.
\end{align*}

Solution:
Let $S$ be the set defined by
\begin{align*}
S = \left\{ \frac{(n+m)^2}{2^{nm}} : n, m \in \mathbb{N} \right\}.
\end{align*}
Let $a_{n,m} = \frac{(n+m)^2}{2^{nm}}$. We wish to find $\inf S$ and $\sup S$.

\begin{proof}[Solution]
\textbf{Part 1: The Infimum}

First, observe that for all $n, m \in \mathbb{N}$, $(n+m)^2 > 0$ and $2^{nm} > 0$. Thus, $a_{n,m} > 0$ for all elements in $S$. This implies that $0$ is a lower bound for $S$.

To show that $0$ is the greatest lower bound (infimum), we must demonstrate that there exist elements in $S$ arbitrarily close to $0$. Consider the subset of terms where $n=1$. Let $x_m = a_{1,m}$. Then:
\begin{align*}
x_m = \frac{(1+m)^2}{2^m}.
\end{align*}
We evaluate the limit of this sequence as $m \to \infty$. Using the standard growth hierarchy between polynomial and exponential functions (or applying L'Hôpital's rule twice to the continuous function $f(x) = (1+x)^2/2^x$), we have:
\begin{align*}
\lim_{m \to \infty} \frac{(1+m)^2}{2^m} = 0.
\end{align*}
Since $S$ contains a sequence converging to $0$ and $0$ is a lower bound, we conclude:
\begin{align*}
\inf S = 0.
\end{align*}

\textbf{Part 2: The Supremum}

Since $a_{n,m}$ is symmetric with respect to $n$ and $m$ (i.e., $a_{n,m} = a_{m,n}$), we assume without loss of generality that $n \le m$. We analyze the values of $a_{n,m}$ by separating the cases $n=1$ and $n \ge 2$.

\textit{Case 1: $n=1$.}
Consider the sequence $u_m = a_{1,m} = \frac{(m+1)^2}{2^m}$ for $m \ge 1$. We calculate the first few terms:
\begin{align*}
u_1 &= \frac{(1+1)^2}{2^1} = \frac{4}{2} = 2, \\
u_2 &= \frac{(1+2)^2}{2^2} = \frac{9}{4} = 2.25, \\
u_3 &= \frac{(1+3)^2}{2^3} = \frac{16}{8} = 2.
\end{align*}
We examine the monotonicity of the sequence for $m \ge 2$ by analyzing the ratio of consecutive terms:
\begin{align*}
\frac{u_{m+1}}{u_m} &= \frac{(m+2)^2}{2^{m+1}} \cdot \frac{2^m}{(m+1)^2} \\
&= \frac{1}{2} \left(\frac{m+2}{m+1} \right)^2 \\
&= \frac{1}{2} \left(1 + \frac{1}{m+1} \right)^2.
\end{align*}
We want to determine when this ratio is less than $1$.
\begin{align*}
\frac{1}{2} \left(1 + \frac{1}{m+1} \right)^2 < 1 \iff \left(1 + \frac{1}{m+1} \right)^2 < 2.
\end{align*}
For $m=2$, we have $\left(1 + \frac{1}{3} \right)^2 = \left(\frac{4}{3}\right)^2 = \frac{16}{9} \approx 1.77$, which is less than $2$. Since the term $\left(1 + \frac{1}{m+1} \right)$ decreases as $m$ increases, the ratio $\frac{u_{m+1}}{u_m}$ is strictly less than $1$ for all $m \ge 2$.
Thus, the sequence is strictly decreasing for $m \ge 2$. The maximum value for the case $n=1$ is therefore achieved at $m=2$:
\begin{align*}
\max_{m \in \mathbb{N}} a_{1,m} = a_{1,2} = \frac{9}{4}.
\end{align*}

\textit{Case 2: $n \ge 2$.}
Assume $2 \le n \le m$. We establish an upper bound for these terms.
Since $n \le m$, we have $n+m \le 2m$.
Since $n \ge 2$, we have $nm \ge 2m$.
Applying these inequalities to $a_{n,m}$:
\begin{align*}
a_{n,m} = \frac{(n+m)^2}{2^{nm}} \le \frac{(2m)^2}{2^{2m}} = \frac{4m^2}{4^m}.
\end{align*}
Let $v_m = \frac{4m^2}{4^m}$. We check the value at the smallest possible $m$ in this case, which is $m=2$ (since $m \ge n \ge 2$):
\begin{align*}
v_2 = \frac{4(2)^2}{4^2} = \frac{16}{16} = 1.
\end{align*}
Now we check if $v_m$ is decreasing for $m \ge 2$. Consider the ratio:
\begin{align*}
\frac{v_{m+1}}{v_m} = \frac{4(m+1)^2}{4^{m+1}} \cdot \frac{4^m}{4m^2} = \frac{1}{4} \left(\frac{m+1}{m} \right)^2 = \frac{1}{4} \left(1 + \frac{1}{m} \right)^2.
\end{align*}
For $m \ge 2$, the maximum value of $\left(1 + \frac{1}{m} \right)^2$ occurs at $m=2$, which is $(1.5)^2 = 2.25$. Thus:
\begin{align*}
\frac{v_{m+1}}{v_m} \le \frac{2.25}{4} < 1.
\end{align*}
So $v_m$ is a decreasing sequence. Consequently, for all $n \ge 2$ and $m \ge n$:
\begin{align*}
a_{n,m} \le v_m \le v_2 = 1.
\end{align*}

\textit{Conclusion.}
Comparing the maximum values from the two cases:
\begin{itemize}
    \item Case $n=1$: Maximum is $\frac{9}{4} = 2.25$.
    \item Case $n \ge 2$: Upper bound is $1$.
\end{itemize}
Since $2.25 > 1$, the supremum of the set is $\frac{9}{4}$. Since this value is achieved by an element of the set (specifically $n=1, m=2$ and $n=2, m=1$), it is the maximum.

\textbf{Final Answer:}
\begin{align*}
\inf S = 0, \quad \sup S = \frac{9}{4}.
\end{align*}
\end{proof}

