Solve:
    \begin{itemize}
        \item{$x_1' = x_2 + e^{3t}$, $x_2' = x_1 - 3e^{3t}$}
        \item{$x_1' = -x_1 + x_2 + 10\cos t$, $x_2' = -3x_1 - x_2 - 10\sin t$}
        \item{$x_1' = x_1 + 4x_2 - 2\cos t$, $x_2' = x_1 + x_2 - \cos t + \sin t$}
    \end{itemize}

Solution:
\textbf{Problem 1}

We are given the system of linear differential equations:
\begin{align*}
    x_1' &= x_2 + e^{3t} \\
    x_2' &= x_1 - 3e^{3t}
\end{align*}

We can express this system in matrix form as $\mathbf{x}' = A\mathbf{x} + \mathbf{g}(t)$, where:
\begin{align*}
    \mathbf{x} = \begin{pmatrix} x_1 \\ x_2 \end{pmatrix}, \quad A = \begin{pmatrix} 0 & 1 \\ 1 & 0 \end{pmatrix}, \quad \mathbf{g}(t) = \begin{pmatrix} 1 \\ -3 \end{pmatrix} e^{3t}
\end{align*}

First, we find the complementary solution $\mathbf{x}_c(t)$ by solving the homogeneous system $\mathbf{x}' = A\mathbf{x}$. We determine the eigenvalues of $A$ by solving the characteristic equation $\det(A - \lambda I) = 0$:
\begin{align*}
    \det \begin{pmatrix} -\lambda & 1 \\ 1 & -\lambda \end{pmatrix} = \lambda^2 - 1 = 0
\end{align*}
The eigenvalues are $\lambda_1 = 1$ and $\lambda_2 = -1$. 

Next, we find the corresponding eigenvectors. For $\lambda_1 = 1$:
\begin{align*}
    (A - I)\mathbf{v}_1 = \begin{pmatrix} -1 & 1 \\ 1 & -1 \end{pmatrix} \begin{pmatrix} v_{11} \\ v_{12} \end{pmatrix} = \begin{pmatrix} 0 \\ 0 \end{pmatrix} \implies \mathbf{v}_1 = \begin{pmatrix} 1 \\ 1 \end{pmatrix}
\end{align*}
For $\lambda_2 = -1$:
\begin{align*}
    (A + I)\mathbf{v}_2 = \begin{pmatrix} 1 & 1 \\ 1 & 1 \end{pmatrix} \begin{pmatrix} v_{21} \\ v_{22} \end{pmatrix} = \begin{pmatrix} 0 \\ 0 \end{pmatrix} \implies \mathbf{v}_2 = \begin{pmatrix} 1 \\ -1 \end{pmatrix}
\end{align*}
The complementary solution is therefore:
\begin{align*}
    \mathbf{x}_c(t) = c_1 e^t \begin{pmatrix} 1 \\ 1 \end{pmatrix} + c_2 e^{-t} \begin{pmatrix} 1 \\ -1 \end{pmatrix}
\end{align*}

To find a particular solution $\mathbf{x}_p(t)$, we use the method of undetermined coefficients. Since $\mathbf{g}(t) = \mathbf{u} e^{3t}$ and $3$ is not an eigenvalue of $A$, we assume a particular solution of the form $\mathbf{x}_p(t) = \mathbf{a} e^{3t}$, where $\mathbf{a}$ is a constant vector. Substituting this into the non-homogeneous equation yields:
\begin{align*}
    3\mathbf{a} e^{3t} &= A\mathbf{a} e^{3t} + \begin{pmatrix} 1 \\ -3 \end{pmatrix} e^{3t} \\
    (3I - A)\mathbf{a} &= \begin{pmatrix} 1 \\ -3 \end{pmatrix}
\end{align*}
We compute $3I - A$ and solve for $\mathbf{a}$:
\begin{align*}
    \begin{pmatrix} 3 & -1 \\ -1 & 3 \end{pmatrix} \begin{pmatrix} a_1 \\ a_2 \end{pmatrix} = \begin{pmatrix} 1 \\ -3 \end{pmatrix}
\end{align*}
This gives the system of equations $3a_1 - a_2 = 1$ and $-a_1 + 3a_2 = -3$. From the second equation, $a_1 = 3a_2 + 3$. Substituting into the first equation:
\begin{align*}
    3(3a_2 + 3) - a_2 &= 1 \\
    8a_2 + 9 &= 1 \implies 8a_2 = -8 \implies a_2 = -1
\end{align*}
Then $a_1 = 3(-1) + 3 = 0$. Thus, $\mathbf{a} = \begin{pmatrix} 0 \\ -1 \end{pmatrix}$, and the particular solution is:
\begin{align*}
    \mathbf{x}_p(t) = \begin{pmatrix} 0 \\ -1 \end{pmatrix} e^{3t}
\end{align*}

The general solution is $\mathbf{x}(t) = \mathbf{x}_c(t) + \mathbf{x}_p(t)$, which can be written in scalar form as:
\begin{align*}
    x_1(t) &= c_1 e^t + c_2 e^{-t} \\
    x_2(t) &= c_1 e^t - c_2 e^{-t} - e^{3t}
\end{align*}

\vspace{1em}
\textbf{Problem 2}

The system is given by:
\begin{align*}
    x_1' &= -x_1 + x_2 + 10\cos t \\
    x_2' &= -3x_1 - x_2 - 10\sin t
\end{align*}

In matrix form, $\mathbf{x}' = A\mathbf{x} + \mathbf{g}(t)$, we have:
\begin{align*}
    A = \begin{pmatrix} -1 & 1 \\ -3 & -1 \end{pmatrix}, \quad \mathbf{g}(t) = \begin{pmatrix} 10 \\ 0 \end{pmatrix} \cos t + \begin{pmatrix} 0 \\ -10 \end{pmatrix} \sin t
\end{align*}

We first solve the homogeneous equation $\mathbf{x}' = A\mathbf{x}$. The characteristic equation is:
\begin{align*}
    \det \begin{pmatrix} -1-\lambda & 1 \\ -3 & -1-\lambda \end{pmatrix} = (-1-\lambda)^2 + 3 = \lambda^2 + 2\lambda + 4 = 0
\end{align*}
Using the quadratic formula, the eigenvalues are $\lambda = -1 \pm i\sqrt{3}$. We find the eigenvector for $\lambda = -1 + i\sqrt{3}$:
\begin{align*}
    (A - (-1 + i\sqrt{3})I)\mathbf{v} = \begin{pmatrix} -i\sqrt{3} & 1 \\ -3 & -i\sqrt{3} \end{pmatrix} \begin{pmatrix} v_1 \\ v_2 \end{pmatrix} = \begin{pmatrix} 0 \\ 0 \end{pmatrix}
\end{align*}
Choosing $v_1 = 1$ yields $v_2 = i\sqrt{3}$, so the complex eigenvector is $\mathbf{v} = \begin{pmatrix} 1 \\ i\sqrt{3} \end{pmatrix}$. The corresponding complex solution is:
\begin{align*}
    \mathbf{x}(t) &= e^{(-1+i\sqrt{3})t} \begin{pmatrix} 1 \\ i\sqrt{3} \end{pmatrix} \\
    &= e^{-t} (\cos(\sqrt{3}t) + i\sin(\sqrt{3}t)) \begin{pmatrix} 1 \\ i\sqrt{3} \end{pmatrix} \\
    &= e^{-t} \begin{pmatrix} \cos(\sqrt{3}t) + i\sin(\sqrt{3}t) \\ i\sqrt{3}\cos(\sqrt{3}t) - \sqrt{3}\sin(\sqrt{3}t) \end{pmatrix}
\end{align*}
Separating this into real and imaginary parts provides two linearly independent real solutions. The complementary solution is:
\begin{align*}
    \mathbf{x}_c(t) = c_1 e^{-t} \begin{pmatrix} \cos(\sqrt{3}t) \\ -\sqrt{3}\sin(\sqrt{3}t) \end{pmatrix} + c_2 e^{-t} \begin{pmatrix} \sin(\sqrt{3}t) \\ \sqrt{3}\cos(\sqrt{3}t) \end{pmatrix}
\end{align*}

To find the particular solution, we use undetermined coefficients. We assume a solution of the form $\mathbf{x}_p(t) = \mathbf{a} \cos t + \mathbf{b} \sin t$, where $\mathbf{a}$ and $\mathbf{b}$ are constant vectors. Differentiating gives $\mathbf{x}_p'(t) = -\mathbf{a} \sin t + \mathbf{b} \cos t$. Substituting into the non-homogeneous system yields:
\begin{align*}
    -\mathbf{a} \sin t + \mathbf{b} \cos t = A(\mathbf{a} \cos t + \mathbf{b} \sin t) + \mathbf{u} \cos t + \mathbf{v} \sin t
\end{align*}
where $\mathbf{u} = \begin{pmatrix} 10 \\ 0 \end{pmatrix}$ and $\mathbf{v} = \begin{pmatrix} 0 \\ -10 \end{pmatrix}$. Equating the coefficients of $\cos t$ and $\sin t$ produces a system of vector equations:
\begin{align*}
    \mathbf{b} &= A\mathbf{a} + \mathbf{u} \\
    -\mathbf{a} &= A\mathbf{b} + \mathbf{v}
\end{align*}
Substitute the first equation into the second to eliminate $\mathbf{b}$:
\begin{align*}
    -\mathbf{a} &= A(A\mathbf{a} + \mathbf{u}) + \mathbf{v} \\
    -\mathbf{a} &= A^2\mathbf{a} + A\mathbf{u} + \mathbf{v} \\
    (I + A^2)\mathbf{a} &= -A\mathbf{u} - \mathbf{v}
\end{align*}
We compute $A^2$:
\begin{align*}
    A^2 = \begin{pmatrix} -1 & 1 \\ -3 & -1 \end{pmatrix} \begin{pmatrix} -1 & 1 \\ -3 & -1 \end{pmatrix} = \begin{pmatrix} -2 & -2 \\ 6 & -2 \end{pmatrix}
\end{align*}
Thus, $I + A^2 = \begin{pmatrix} -1 & -2 \\ 6 & -1 \end{pmatrix}$. Next, we compute the right-hand side vector $-A\mathbf{u} - \mathbf{v}$:
\begin{align*}
    A\mathbf{u} &= \begin{pmatrix} -1 & 1 \\ -3 & -1 \end{pmatrix} \begin{pmatrix} 10 \\ 0 \end{pmatrix} = \begin{pmatrix} -10 \\ -30 \end{pmatrix} \\
    -A\mathbf{u} - \mathbf{v} &= \begin{pmatrix} 10 \\ 30 \end{pmatrix} - \begin{pmatrix} 0 \\ -10 \end{pmatrix} = \begin{pmatrix} 10 \\ 40 \end{pmatrix}
\end{align*}
We solve $(I + A^2)\mathbf{a} = \begin{pmatrix} 10 \\ 40 \end{pmatrix}$:
\begin{align*}
    \begin{pmatrix} -1 & -2 \\ 6 & -1 \end{pmatrix} \begin{pmatrix} a_1 \\ a_2 \end{pmatrix} = \begin{pmatrix} 10 \\ 40 \end{pmatrix}
\end{align*}
This gives $-a_1 - 2a_2 = 10$ and $6a_1 - a_2 = 40$. From the first equation, $a_1 = -2a_2 - 10$. Substituting into the second:
\begin{align*}
    6(-2a_2 - 10) - a_2 &= 40 \\
    -13a_2 - 60 &= 40 \implies -13a_2 = 100 \implies a_2 = -\frac{100}{13}
\end{align*}
Then $a_1 = -2\left(-\frac{100}{13}\right) - 10 = \frac{200}{13} - \frac{130}{13} = \frac{70}{13}$. So $\mathbf{a} = \begin{pmatrix} 70/13 \\ -100/13 \end{pmatrix}$. Now we find $\mathbf{b} = A\mathbf{a} + \mathbf{u}$:
\begin{align*}
    \mathbf{b} &= \begin{pmatrix} -1 & 1 \\ -3 & -1 \end{pmatrix} \begin{pmatrix} 70/13 \\ -100/13 \end{pmatrix} + \begin{pmatrix} 10 \\ 0 \end{pmatrix} \\
    &= \begin{pmatrix} -170/13 \\ -110/13 \end{pmatrix} + \begin{pmatrix} 130/13 \\ 0 \end{pmatrix} = \begin{pmatrix} -40/13 \\ -110/13 \end{pmatrix}
\end{align*}
The particular solution is $\mathbf{x}_p(t) = \begin{pmatrix} 70/13 \\ -100/13 \end{pmatrix} \cos t + \begin{pmatrix} -40/13 \\ -110/13 \end{pmatrix} \sin t$. Combining the complementary and particular solutions, the general solution is:
\begin{align*}
    x_1(t) &= c_1 e^{-t} \cos(\sqrt{3}t) + c_2 e^{-t} \sin(\sqrt{3}t) + \frac{70}{13}\cos t - \frac{40}{13}\sin t \\
    x_2(t) &= -c_1 \sqrt{3} e^{-t} \sin(\sqrt{3}t) + c_2 \sqrt{3} e^{-t} \cos(\sqrt{3}t) - \frac{100}{13}\cos t - \frac{110}{13}\sin t
\end{align*}

\vspace{1em}
\textbf{Problem 3}

The system is given by:
\begin{align*}
    x_1' &= x_1 + 4x_2 - 2\cos t \\
    x_2' &= x_1 + x_2 - \cos t + \sin t
\end{align*}

In matrix form, $\mathbf{x}' = A\mathbf{x} + \mathbf{g}(t)$, we have:
\begin{align*}
    A = \begin{pmatrix} 1 & 4 \\ 1 & 1 \end{pmatrix}, \quad \mathbf{g}(t) = \begin{pmatrix} -2 \\ -1 \end{pmatrix} \cos t + \begin{pmatrix} 0 \\ 1 \end{pmatrix} \sin t
