Prove the Weierstrass inequalities: If $0 < a_k < 1$ and $\sum_{k=1}^{n} a_k < 1$, then
\begin{enumerate}
\item{$1 + \sum_{k=1}^{n} a_k < \prod_{k=1}^{n} (1 + a_k) < \frac{1}{1 - \displaystyle\sum_{k=1}^{n} a_k}$}
\item{$1 - \sum_{k=1}^{n} a_k < \prod_{k=1}^{n} (1 - a_k) < \frac{1}{1 + \displaystyle\sum_{k=1}^{n} a_k}$}
\end{enumerate}

Show that
\begin{enumerate}
  \item{ if a sequence $\{a_n\}$ is monotonically increasing, then $\displaystyle \lim_{n \to \infty} a_n = \sup\{a_n : n \in \mathbb{N}\}$}
  \item{ if a sequence $\{a_n\}$ is monotonically decreasing, then $\displaystyle \lim_{n \to \infty} a_n = \inf\{a_n : n \in \mathbb{N}\}$}
\end{enumerate}
